// Üretilen dosya: tool/ozgun/uret.py. Tarih · Yazı, kâğıt, matbaa, kütüphaneler, medreseler ve üniversiteler tarihi (çivi yazısı, parşömen, İskenderiye, Beytülhikme, Nizamiye, Sahn-ı Seman, ilk üniversiteler) (zor).
const ozHistory17Zor = <(String, String, List<String>, String)>[
  ('Üç dilli (Eski Farsça, Elamca, Babilce) yapısıyla çivi yazısının çözülmesinde kilit rol oynayan anıtsal kaya kabartması hangisidir?', 'Behistun Yazıtı', ['Rosetta Taşı', 'Karatepe Yazıtı', 'Orhun Abideleri'], 'İran\'ın Kirmanşah yakınlarındaki Behistun (Bisütun) Yazıtı, Pers Kralı I. Darius döneminde üç farklı çivi yazısı diliyle kazınmış ve deşifrede anahtar olmuştur.'),
  ('19. yüzyılda Behistun Yazıtı\'ndaki Eski Farsça ve Babilce çivi yazılı metinleri kopyalayıp çözerek Asurolojinin temelini atan araştırmacı kimdir?', 'Henry Creswicke Rawlinson', ['Jean-François Champollion', 'Bedrich Hrozny', 'Michael Ventris'], 'İngiliz subay ve şarkiyatçı Henry Rawlinson, sarp kayalıklardaki Behistun Yazıtı\'nı kopyalayıp Eski Farsça üzerinden çivi yazısının çözülmesini sağlamıştır.'),
  ('Hitit çivi yazısıyla kaleme alınmış metinleri çözerek Hititçenin Hint-Avrupa dil ailesine ait olduğunu kanıtlayan bilim insanı kimdir?', 'Bedrich Hrozny', ['Georg Friedrich Grotefend', 'Heinrich Schliemann', 'Hugo Winckler'], 'Çek dilbilimci Bedrich Hrozny, 1915-1917 yıllarında Boğazköy kil tabletlerini inceleyerek Hitit çivi yazısını çözmüştür.'),
  ('MÖ 14. yüzyıla ait Amarna Mektupları\'nın Mısır\'da bulunmasına rağmen Akadca çivi yazısıyla kil tabletlere yazılmış olması neyi kanıtlar?', 'Akadca ve çivi yazısının o dönemde Yakın Doğu\'nun ortak diplomasi dili olduğunu', ['Mısır firavunlarının kendi hiyeroglif yazılarını tamamen terk ettiğini', 'Mısır\'da papirüs üretiminin kuraklık nedeniyle uzun süre durduğunu', 'Babil Krallığı\'nın Mısır topraklarını askeri olarak egemenliği altına aldığını'], 'Amarna arşivi, Mısır, Hitit, Babil ve Mitanni gibi devletler arasındaki uluslararası diplomaside Akadca çivi yazısının "lingua franca" olduğunu gösterir.'),
  ('MÖ 14. yüzyılda Kuzey Suriye\'deki Ras Şamra antik kentinde kullanılan ve çivi yazısı işaretleriyle oluşturulan ilk alfabetik sistem hangisidir?', 'Ugarit alfabesi', ['Arami alfabesi', 'Nebati alfabesi', 'Girit çizgisel yazısı'], 'Ugarit kentinde bulunan kil tabletlerdeki yaklaşık 30 işaretlik sistem, çivi yazısı tekniğini kullanan bilinen en erken ünsüz alfabesidir.'),
  ('MÖ 7. yüzyıldan itibaren Mısır\'da idari, hukuki ve günlük işlerde yaygınlaşan, Yunanca "halk yazısı" anlamındaki en işlek yazı türü hangisidir?', 'Demotik', ['Hiyeratik', 'Piktografik', 'İdeografik'], 'Demotik yazı, Geç Dönem ve Ptolemaioslar Mısır\'ında günlük ve idari metinlerde kullanılan oldukça sadeleştirilmiş işlek yazıdır.'),
  ('Champollion\'un Mısır hiyerogliflerini çözerken önceki araştırmacıların düştüğü hangi temel yanılgıyı aşması belirleyici olmuştur?', 'Hiyerogliflerin yalnızca sembolik resimler değil aynı zamanda fonetik ses işaretleri içerdiğini fark etmesi', ['Rosetta Taşı\'ndaki Yunanca metnin aslında fermanın özeti değil tamamen farklı bir dini ilahi olduğunu bulması', 'Mısır dilinin Sami dilleriyle değil eski Çin yazı sistemiyle aynı kökten türediğini kanıtlaması', 'Demotik yazının sağdan sola değil yukarıdan aşağıya doğru sütunlar halinde okunduğunu keşfetmesi'], 'Rönesans\'tan beri hiyerogliflerin salt mistik-sembolik ideogramlar olduğu sanılıyordu; Champollion sistemin hem fonetik hem ideografik olduğunu kanıtladı.'),
  ('Champollion\'dan önce Rosetta Taşı üzerinde çalışarak kartuşların kral isimleri içerdiğini ve Demotik yazının hiyeroglifle ilişkisini bulan İngiliz bilim insanı kimdir?', 'Thomas Young', ['Sylvestre de Sacy', 'Arthur Evans', 'Flinders Petrie'], 'Fizikçi ve hekim Thomas Young, Ptolemaios kartuşundaki bazı fonetik değerleri ve Demotik-hiyeroglif bağını saptayarak önemli bir ön adım atmıştır.'),
  ('Mısır hiyeroglif sisteminde kelimenin sonuna eklenen, okunmayan ancak kelimenin hangi anlam kategorisine girdiğini belirten işaretlere ne denir?', 'Determinatif (belirleyici işaret)', ['Fonogram (ses işareti)', 'Ligatür (bitişik harf)', 'Punktasyon (noktalama işareti)'], 'Ünlülerin yazılmadığı Mısır yazısında eş sesli kelimeleri ayırt etmek için kelime sonuna anlam sınıfını gösteren determinatifler konulurdu.'),
  ('Batı dillerindeki "paper" (kâğıt) ve "bible" (Kitab-ı Mukaddes / kitap) kelimelerinin kökeni sırasıyla hangi iki tarihsel kavrama dayanır?', 'Papirüs bitkisi ve papirüs ticaretiyle ünlü Fenike liman kenti Byblos', ['Bergama parşömeni ve Babil Krallığı\'nın başkentindeki tapınak kütüphanesi', 'Çin\'deki dut ağacı lifi ve İskenderiye Kütüphanesi\'ndeki rulo katalogları', 'Roma\'daki balmumu tabletler ve Atina\'daki felsefe okullarının ders notları'], '"Paper" Mısır\'ın papirüsünden; Yunanca kitap anlamındaki "biblion" ve "Bible" ise Mısır\'dan papirüs ithal eden Fenike limanı Byblos\'tan (Gubla) gelir.'),
  ('Papirüs rulosunun kullanım açısından daha sonra yaygınlaşacak olan kodeks formuna kıyasla en belirgin işlevsel kısıtlılığı nedir?', 'Metnin ortasındaki belirli bir bölüme ulaşmak için rulonun boydan boya açılması gerekmesi', ['Üzerine kamış kalem ve is mürekkebi ile yazı yazılmasının teknik olarak çok zor olması', 'Kil tabletlere kıyasla çok daha ağır olduğu için raflarda depolanamaması', 'Yalnızca hiyeroglif gibi resim yazılarının yazımına uygun dokuya sahip olması'], 'Rulo formunda rastgele erişim (sayfa çevirme) yoktur; okuyucu aradığı pasajı bulmak için bir eliyle ruloyu açıp diğer eliyle sarmak zorundaydı.'),
  ('Mısır\'ın Sina Yarımadası\'ndaki Serabit el-Hadim turkuaz madenlerinde bulunan ve Mısır hiyerogliflerinden Fenike alfabesine geçiş halkasını oluşturan yazı hangisidir?', 'Proto-Sinaitik yazı', ['Girit Linear A yazısı', 'Kıbrıs hece yazısı', 'Etrüsk alfabesi'], 'MÖ 19.-16. yüzyıllarda Sina madenlerinde çalışan Kenanlı/Sami işçiler, Mısır hiyerogliflerini akrofoni ilkesiyle kendi dillerinin ünsüz seslerine uyarlayarak Proto-Sinaitik yazıyı oluşturmuştur.'),
  ('Fenike alfabesinin oluşumunda kullanılan ve "bir nesne resminin, o nesnenin Sami dilindeki adının ilk ünsüz sesini temsil etmesi" ilkesine ne ad verilir?', 'Akrofoni ilkesi', ['Boustrophedon tekniği', 'İdeografik aktarım', 'Rebus (bilmece) kuralı'], 'Örneğin Sami dilinde "öküz" anlamına gelen "\'alp" (alef) kelimesinin öküz başı resmi, artık öküzü değil kelimenin ilk sesi olan gırtlak ünsüzünü temsil etmiştir (akrofoni).'),
  ('Erken Yunan ve Anadolu yazıtlarında bir satırın sağdan sola, alt satırın ise tarla süren öküzün dönüşü gibi soldan sağa yazılması tekniğine ne denir?', 'Boustrophedon', ['Palimpsest', 'Kaligrafi', 'Kriptografi'], 'Yunanca "öküz dönüşü" anlamına gelen boustrophedon, Fenike\'nin sağdan sola yazımından Yunanların soldan sağa standart yazımına geçiş evresinde kullanılmıştır.'),
  ('Fenike alfabesinden türeyen Arami alfabesinin Orta Doğu ve Orta Asya yazı tarihi açısından üstlendiği tarihsel rol aşağıdakilerden hangisidir?', 'İbrani, Nebati-Arap, Süryani, Soğd ve Uygur gibi birçok Doğu alfabesinin ana kaynağı olması', ['Çin karakterlerinin tamamen terk edilerek Doğu Asya\'da harf yazısına geçilmesini sağlaması', 'Avrupa\'da Slav halklarının kullandığı Kiril alfabesinin doğrudan temelini oluşturması', 'Mısır\'da hiyeroglif yazısının MÖ 2000 yılından itibaren unutulmasına yol açması'], 'Pers İmparatorluğu\'nun resmi idari yazısı olan Arami alfabesi; batıda İbrani ve Arap (Nebati üzerinden), doğuda Pehlevi, Soğd, Uygur ve Moğol alfabelerinin atası olmuştur.'),
  ('Mezopotamya\'da kâtiplerin kimlik ve mülkiyet onayı için ıslak kil tablet üzerinde yuvarlayarak kesintisiz kabartma sahneler oluşturdukları araç nedir?', 'Silindir mühür', ['Damga sikke', 'Kartuş yüzük', 'Bronz şablon'], 'Değerli taşlardan oyulan silindir mühürler, ıslak kil tablet veya kil zarf üzerinde yuvarlandığında sahibine özgü mitolojik sahne ve yazıt izi bırakırdı.'),
  ('Bir arkeolog, üzerinde sağdan sola yazılmış 22 ünsüz harf bulunan ve hiçbir sesli harf işareti içermeyen MÖ 9. yüzyıl tarihli bir Doğu Akdeniz yazıtı bulduğunda bunu öncelikle hangi yazı ailesiyle ilişkilendirmelidir?', 'Kuzeybatı Sami / Fenike yazı ailesi', ['Ege / Girit Çizgisel B hece yazısı', 'Anadolu Luvi hiyeroglif sistemi', 'Erken Klasik Dönem Yunan alfabesi'], 'MÖ 9. yüzyılda sağdan sola yazılan ve yalnızca 22 ünsüzden oluşan sistem Fenike ve yakın Kuzeybatı Sami (Arami, Eski İbrani, Moab) alfabelerinin tipik özelliğidir.'),
  ('Mezopotamya\'da Hammurabi Kanunları\'nın kil tabletlerin yanı sıra 2,25 metrelik siyah diorit taş bir stel üzerine çivi yazısıyla kazınmasının temel siyasi amacı nedir?', 'Hukuk kurallarının kalıcılığını ve kralın tanrı Şamaş\'tan aldığı adalet yetkisini kamusal alanda simgelemek', ['Kil tabletlerin Babil ikliminde birkaç gün içinde eriyip okunmaz hale gelmesini önlemek', 'Okuma yazma bilmeyen yabancı tüccarların taş üzerindeki harfleri dokunarak tanımasını sağlamak', 'Taş stellerin komşu krallıklara elçiler aracılığıyla kolayca taşınabilmesini mümkün kılmak'], 'Günlük hukuk kayıtları kil tabletlere yazılırken, anıtsal taş stel tapınak meydanına dikilerek kralın ilahi meşruiyetini ve yasaların değişmezliğini ilan etmek için kullanılmıştır.'),
  ('MÖ 2. binyılda Girit ve Yunan anakarasında Miken uygarlığının kil tabletler üzerine yazdığı ve 1952\'de Michael Ventris tarafından çözülen hece yazısı hangisidir?', 'Linear B (Çizgisel B) yazısı', ['Linear A (Çizgisel A) yazısı', 'Phaistos Diski yazısı', 'Kıbrıs-Minos yazısı'], 'İngiliz mimar ve amatör dilbilimci Michael Ventris, John Chadwick\'in katkısıyla Linear B tabletlerini çözerek bunların Erken Yunanca olduğunu kanıtlamıştır.'),
  ('Tarihte bilinen son tarihli Mısır hiyeroglif yazıtı (MS 394, Graffito of Esmet-Akhom) hangi tapınak kompleksinde yer almaktadır?', 'Philae (Filai) İsis Tapınağı', ['Karnak Amon Tapınağı', 'Ebu Simbel Tapınağı', 'Luksor Tapınağı'], 'Güney Mısır\'daki Philae Adası\'nda bulunan İsis Tapınağı duvarına MS 24 Ağustos 394\'te kazınan yazıt, tarihlenebilen son antik hiyeroglif metindir.'),
  ('MÖ 3. binyıl ortalarında Kuzey Suriye\'de yer alan ve yaklaşık 17.000 çivi yazılı kil tabletten oluşan devlet arşiviyle Yakın Doğu tarihini aydınlatan antik kent hangisidir?', 'Ebla (Tell Mardikh)', ['Palmira (Tedmür)', 'Petra', 'Sayda (Sidon)'], 'İtalyan arkeolog Paolo Matthiae tarafından 1974-75\'te keşfedilen Ebla Kraliyet Arşivi, MÖ 2400-2300 civarında Sümer çivi yazısının Suriye\'de yerel Ebla dilinde kullanıldığını göstermiştir.'),
  ('İskenderiye Kütüphanesi\'nde bilgin Kallimakhos\'un hazırladığı "Pinakes" adlı eserin kitap ve kütüphanecilik tarihindeki önemi nedir?', 'Papirüs rulolarını konularına ve yazarlarına göre sınıflandıran ilk sistematik kütüphane kataloğu olması', ['Papirüs yerine parşömen kullanımını zorunlu kılan ilk kraliyet yasası olması', 'Mısır hiyerogliflerini Yunancaya çeviren ilk resimli ansiklopedi olması', 'Matbaa harflerinin döküm oranlarını belirleyen ilk teknik el kitabı olması'], 'Kallimakhos\'un 120 ruloluk "Pinakes" (Levhalar) çalışması, İskenderiye\'deki eserleri türlerine (destan, tarih, tıp, felsefe vb.) ve yazar biyografilerine göre dizinleyen ilk bibliyografik katalogdur.'),
  ('Hitit İmparatorluğu\'nda başkent Hattuşaş\'taki devlet arşivlerinde kil tabletlerde çivi yazısı kullanılırken, açık hava kaya anıtlarında ve mühürlerde Luvi hiyeroglifinin tercih edilmesinin nedeni nedir?', 'Halkın görebileceği kamusal anıtlarda görsel etkisi yüksek yerli hiyeroglif geleneğinin siyasi prestij sağlaması', ['Çivi yazısının sert kaya yüzeylerine metal keskilerle kazınmasının fiziksel olarak imkânsız olması', 'Mezopotamyalı tüccarların Hititlerin kaya anıtlarında çivi yazısı kullanmasını antlaşmayla yasaklaması', 'Luvi hiyeroglifinin kil tablet üzerine yazıldığında kilin çatlamasına neden olması'], 'Hititler bürokraside Mezopotamya kökenli çivi yazısını kullanırken, kamusal kaya kabartmalarında ve kraliyet mühürlerinde Anadolu\'ya özgü Luvi hiyeroglifini tercih ederek görsel iktidar dili kurmuştur.'),
  ('MÖ 9. yüzyıla tarihlenen ve Moab Kralı Meşa\'nın İsrail Krallığı\'na karşı zaferini Fenike kökenli alfabeyle anlattığı bazalt anıt hangisidir?', 'Meşa Steli', ['Merneptah Steli', 'Siyah Obelisk', 'kiklos Yazıtı'], 'Ürdün\'ün Diban bölgesinde bulunan MÖ 840 civarına ait Meşa Steli, Fenike-İbrani kolundaki Kuzeybatı Sami alfabesinin en önemli uzun tarihsel taş yazıtlarından biridir.'),
  ('Yazı tarihinde piktografik sistemden hece yazısına, oradan da ünsüz ve tam sesli alfabeye geçiş süreci genel olarak hangi temel eğilimi yansıtır?', 'İşaret sayısının azalarak yazının kavramsal temsilden konuşma dilinin seslerini kodlamaya doğru soyutlanmasını', ['Kullanılan yazı malzemelerinin giderek daha ağır ve taşınması zor taş anıtlara dönüşmesini', 'Toplumların çok tanrılı dinlerden tek tanrılı dinlere geçiş hızının kâtiplerce sınırlandırılmasını', 'Farklı dillerin gramer kurallarının ortadan kalkarak tek bir evrensel işaret dilinde birleşmesini'], 'Binlerce nesne resminden yüzlerce hece işaretine, oradan 20-30 harflik alfabeye geçiş; işaret sayısında büyük bir tasarruf ve sese dayalı yüksek soyutlama sağlamıştır.'),
  ('Parşömenin en ince, en beyaz ve en pürüzsüz türü olup yeni doğmuş veya ölü doğmuş buzağı, kuzu ya da oğlak derisinden üretilen lüks yazı malzemesine ne ad verilir?', 'Vellum', ['Ostrakon', 'Papirüs', 'Maroken'], 'Latince dana/buzağı anlamındaki "vitulinum" kökünden gelen vellum, Orta Çağ\'da en değerli tezhipli İncil ve dua kitaplarının yazımında kullanılan ince deridir.'),
  ('Parşömenin pahalı olması nedeniyle üzerindeki eski yazının kazınıp yıkanarak silinmesi ve aynı deri üzerine yeniden başka bir metin yazılmasıyla oluşan el yazmalarına ne denir?', 'Palimpsest', ['İnkunabula', 'Faksimile', 'Kolofon'], 'Yunanca "yeniden kazınmış" anlamına gelen palimpsest yazmalarda, modern ultraviyole ve multispektral görüntüleme teknikleriyle alttaki silinmiş antik metinler okunabilmektedir.'),
  ('Orta Çağ\'dan kalma bir dua kitabının sayfaları morötesi (UV) ışık altında incelendiğinde, satırların altında Arşimet\'e ait silinmiş Yunanca geometri çizimleri görülmesi hangi tarihsel uygulamayı kanıtlar?', 'Nadir ve pahalı olan parşömen yapraklarının kazınarak palimpsest yöntemiyle geri dönüştürüldüğünü', ['Matbaa ustalarının aynı metal kalıbı yanlışlıkla iki farklı kitapta üst üste bastığını', 'Kâğıt hamurunun içine eski papirüs rulolarının parçalanarak karıştırıldığını', 'Manastır rahiplerinin Arşimet\'in eserlerini görünmez limon suyu mürekkebiyle çoğalttığını'], 'Ünlü "Arşimet Palimpsesti" örneğinde olduğu gibi, 13. yüzyılda eski bir parşömen yazma kazınıp üzerine dua kitabı yazılmış, modern görüntülemeyle alttaki antik bilim eseri kurtarılmıştır.'),
  ('Rulo formundan kodeks formuna geçişin okuma kültürü ve entelektüel çalışma alışkanlıkları üzerinde yarattığı en önemli dönüşüm nedir?', 'Sayfa numaralandırma, içindekiler dizini oluşturma ve farklı metinlere aynı anda başvurup not alma olanağı sağlaması', ['Kitapların yalnızca yüksek sesle koro halinde okunabilmesi zorunluluğunu getirmesi', 'Bir cildin içine sığdırılabilecek toplam kelime sayısını onda bir oranında azaltması', 'Okuyucunun kitabı tutmak için mutlaka iki elini de sürekli meşgul etmesini gerektirmesi'], 'Ruloda metin kesintisiz bir şeritken, kodeks sayfalı yapısı sayesinde rastgele erişimi, dipnot/kenar notu düşmeyi, çapraz atıf yapmayı ve birden çok eseri tek ciltte toplamayı sağlamıştır.'),
  ('Orta Çağ manastırlarında ve İslam dünyası medreselerinde parşömen üzerine dayanıklı koyu kahverengi-siyah yazı yazmak için meşe mazısı (gall) ve demir sülfat karıştırılarak üretilen mürekkep hangisidir?', 'Demir-mazı mürekkebi', ['Çin çubuk mürekkebi', 'Kurşun beyazı mürekkebi', 'Çivit mavisi mürekkebi'], 'Meşe ağaçlarındaki mazı tanenleri ile demir sülfattan (zaç yağı tuzu) üretilen demir-mazı mürekkebi, parşömen lifleriyle kimyasal bağ kurarak silinmesi çok zor yazılar oluşturmuştur.'),
  ('İslam kitap sanatlarında ham kâğıdın mürekkebi dağıtmasını önlemek ve kalemin yüzeyde pürüzsüz kaymasını sağlamak için nişasta, yumurta akı veya şapla kaplanıp akik taşıyla (mühre) parlatılması işlemine ne denir?', 'Aharlama ve mühreleme', ['Tabaklama ve kireçleme', 'varaklama ve cetvelleme', 'Soğuk damgalama'], 'Ham kâğıt su bazlı is mürekkebini kurutma kâğıdı gibi dağıtacağından, hat sanatında yazım öncesi kâğıt yüzeyine "ahar" sürülür ve "mühre" ile parlatılırdı.'),
  ('13. yüzyıl sonlarında İtalya\'daki Fabriano kâğıt ustalarının geliştirdiği, kâğıt eleğindeki ince tel motif sayesinde ışığa tutulduğunda kâğıt dokusunda görünen üretici işaretine ne ad verilir?', 'Filigran (su izi / watermark)', ['Kolofon (ketebe kaydı)', 'Ekslibris (mülkiyet mührü)', 'Serlevha (başlık tezhibi)'], '1282 civarında İtalya\'nın Fabriano kentinde geliştirilen filigran tekniği, hem üretici loncanın kalite markasını göstermiş hem de modern tarihçilerin kağıtları tarihlemesini sağlamıştır.'),
  ('13. yüzyılda Kutsal Roma İmparatoru II. Friedrich gibi bazı Avrupalı yöneticilerin resmi noter belgelerinde kâğıt kullanımını yasaklayıp parşömeni şart koşmalarının nedeni nedir?', 'Erken dönem kâğıtlarının nem ve böceklere karşı hayvan derisi parşömen kadar dayanıklı olmayacağından endişe edilmesi', ['Kâğıt üzerine Latince harflerin tüy kalemle yazılmasının fiziksel olarak imkânsız olması', 'Avrupa\'daki tüm kâğıtların zehirli kimyasallar içerdiğine dair tıbbi raporlar hazırlanması', 'Matbaa makinelerinin o yüzyılda yalnızca kalın dana derisi üzerine baskı yapabilmesi'], 'Başlangıçta pamuk/paçavra kâğıdı Avrupa\'da kırılgan ve dayanıksız görülmüş; hukuki tapu ve fermanların yüzyıllarca korunması için geleneksel parşömen daha güvenilir sayılmıştır.'),
  ('MS 8. yüzyıl sonunda Şarlman (Charlemagne) dönemindeki Karolenj Rönesansı\'nda Alcuin\'in öncülüğünde geliştirilen, kelimeler arası boşluk ve okunaklı küçük harfleriyle modern matbaa harflerine kaynaklık eden yazı hangisidir?', 'Karolenj minüskülü', ['Roma anıtsal majüskülü', 'Merovenj el yazısı', 'Gotik textura yazısı'], 'Karolenj minüskülü, net küçük harf formları ve kelime ayrımlarıyla okunabilirliği artırmış; 15. yüzyıl İtalyan hümanistleri bunu "antik yazı" sanarak modern Roman tipografisine dönüştürmüştür.'),
  ('1040\'lı yıllarda Çin\'de (Song Hanedanı döneminde) pişmiş kilden tek tek harf/karakter kalıpları yaparak tarihte bilinen ilk hareketli harf baskı sistemini icat eden usta kimdir?', 'Bi Sheng', ['Cai Lun', 'Wang Zhen', 'Zheng He'], 'Bi Sheng, kilden kestiği karakterleri fırınlayıp reçine-balmumu karışımlı demir bir tepsiye dizerek tarihteki ilk hareketli harf (movable type) sistemini geliştirmiştir.'),
  ('Gutenberg\'den yaklaşık yetmiş yıl önce, 1377 yılında Kore\'de (Goryeo Hanedanı) hareketli dökme metal karakterlerle basılan ve günümüze ulaşan en eski metal harfli kitap hangisidir?', 'Jikji', ['Tripitaka Koreana', 'Gutenberg İncili', 'Yongle Ansiklopedisi'], '1377\'de Kore\'de Cheongju Heungdeok Tapınağı\'nda bronz döküm hareketli karakterlerle basılan Budist derleme "Jikji", bilinen en eski hareketli metal harfli basılı kitaptır.'),
  ('Gutenberg\'in döktüğü hareketli metal harflerin ne baskı altında ezilmesi ne de soğurken büzüşüp bozulması için geliştirdiği özel metal alaşımı hangi üç elementten oluşuyordu?', 'Kurşun, kalay ve antimon', ['Demir, bakır ve çinko', 'Altın, gümüş ve nikel', 'Alüminyum, krom ve cıva'], 'Kurşun ucuz ve kolay eriyen ana maddeydi, kalay sertlik ve paslanmazlık katıyordu; antimon ise soğurken hafifçe genleşerek kalıbın en ince harf detaylarını kusursuz doldurmasını sağlıyordu.'),
  ('Kitap tarihinde matbaanın Avrupa\'da icadından 1500 yılının sonuna (1501 başına) kadar geçen "beşik dönemi"nde basılmış tüm erken dönem matbaa kitaplarına verilen özel ad nedir?', 'İnkunabula (incunabula / beşik baskıları)', ['Palimpsest (kazınmış yazmalar)', 'Apokrifa (gizli metinler)', 'Ferman (kraliyet emirleri)'], 'Latince "beşik / kundak" anlamına gelen incunabula terimi, matbaacılık sanatının emekleme/beşik çağı sayılan 1450-1500 yılları arasında basılmış nadir kitapları tanımlar.'),
  ('Avrupa\'da 14. ve 15. yüzyıllarda paçavradan kâğıt üreten su değirmenlerinin yaygınlaşmış olması ile Gutenberg matbaasının başarısı arasında nasıl bir nedensellik ilişkisi vardır?', 'Ucuz ve bol kâğıt üretimi olmasaydı matbaanın yüksek hızda kitap basma kapasitesi pahalı parşömen darboğazına takılıp ekonomik olamazdı', ['Matbaanın icadı Avrupa\'daki tüm kâğıt değirmenlerinin kapanıp yeniden papirüs ithal edilmesine yol açmıştır', 'Kâğıt değirmenleri yalnızca kilise vergi makbuzları ürettiği için kitap basımıyla hiçbir ilişkisi olmamıştır', 'Parşömen kâğıttan çok daha ucuz olduğu için ilk yüz yıl boyunca matbaalarda hiç kâğıt kullanılmamıştır'], 'Tek bir 180 nüshalık İncil baskısı için bile sadece parşömen kullanılsaydı binlerce hayvan derisi gerekirdi; kâğıdın Avrupa\'da hazır ve ucuz bir malzeme haline gelmesi matbaa devrimini ekonomik açıdan mümkün kılmıştır.'),
  ('Matbaanın Bilimsel Devrim (Kopernik, Vesalius, Galileo dönemi) üzerindeki en kritik epistemolojik (bilgi üretimine dair) etkisi aşağıdakilerden hangisidir?', 'Astronomi tablolarının, anatomi çizimlerinin ve haritaların kâtip hataları olmadan birebir aynı standart kopyalarla bilim insanlarınca denetlenip geliştirilebilmesi', ['Bilim insanlarının deney yapmayı bırakıp yalnızca antik filozofların kitaplarını ezberlemesine neden olması', 'Latincenin bilim dili olmaktan çıkarılıp yerine hiyeroglif sembollerinin getirilmesi', 'Tüm bilimsel kitapların devlet sırrı sayılarak halk kütüphanelerinden toplatılması'], 'El yazması çağında her kopyalamada şekiller, haritalar ve rakamlar bozuluyordu; matbaa "özdeş ve hatasız görsel/sayısal çoğaltım" sağlayarak birikimli modern bilimin önünü açmıştır.'),
  ('Rönesans döneminde Venedik\'te kurduğu basımevinde cep boyu (octavo) klasik kitaplar basan, italik (eğik) matbaa harflerini ve noktalı virgül kullanımını yaygınlaştıran ünlü hümanist yayıncı kimdir?', 'Aldus Manutius', ['William Caxton', 'Johannes Mentelin', 'Christophe Plantin'], 'Venedikli Aldus Manutius (Aldine Press), ağır kürsü kitapları yerine elde taşınabilir küçük boy Yunan-Latin klasiklerini basmış ve Francesco Griffo\'ya ilk italik harf karakterlerini tasarlatmıştır.'),
  ('III. Ahmed\'in fermanı ve Şeyhülislam Yenişehirli Abdullah Efendi\'nin fetvasıyla İbrahim Müteferrika\'ya verilen matbaa izninde hangi tür kitapların basımı başlangıçta kapsam dışı tutulmuştur?', 'Kur\'an-ı Kerim, tefsir, hadis ve fıkıh gibi doğrudan dini nitelikteki eserler', ['Tarih, coğrafya, dil sözlükleri, astronomi ve askerlik bilimine dair eserler', 'Yabancı dillerden Türkçeye çevrilen dünya tarihi ve harita kitapları', 'Denizcilik pusulası ve mıknatıs bilimi üzerine yazılmış teknik risaleler'], 'Hattat esnafının geçimini korumak ve kutsal metinlerin baskı hatalarıyla bozulması endişesini gidermek amacıyla ilk aşamada yalnızca sözlük, tarih, coğrafya ve fen bilimleri eserlerinin basılmasına izin verilmiştir.'),
  ('Eski Türklerde Uygurların Soğd kökenli alfabeyle kâğıt üzerine kitaplar yazmasının yanı sıra, 9.-13. yüzyıllarda Turfan ve Dunhuang bölgesinde kitap çoğaltmak için kullandıkları baskı tekniği hangisidir?', 'Ahşap blok baskı ve tahtadan oyulmuş hareketli Uygur harf/kelime kalıpları', ['Gutenberg tipi kurşun-antimon alaşımlı vidalı pres baskısı', 'Balmumu kaplı fildişi levhalar üzerine metal stylus kazıması', 'Mısır\'dan ithal edilen papirüs ruloları üzerine hiyeratik fırça yazısı'], 'Yerleşik kültür ve kitap sanatlarında çok ileri olan Uygurlar, kâğıt imal etmiş, kodeks/pothi cilt formlarını kullanmış ve Turfan kazılarında bulunan sert ağaçtan oyulmuş hareketli harf/kelime kalıplarıyla baskı yapmışlardır.'),
  ('Orta Çağ İslam dünyasında ve Avrupa\'da üniversitelerin (medrese ve studium generale) yükselişiyle birlikte kitap üretim sürecinde yaşanan en önemli kurumsal değişim nedir?', 'Kitap kopyalamanın yalnızca manastır veya saray tekelinden çıkarak şehirlerdeki profesyonel kâtip, verrâk ve pecia (kiralık forma) atölyelerine yayılması', ['Üniversite öğrencilerinin kitap okumayı tamamen bırakıp yalnızca sözlü münazaralarla mezun olması', 'Tüm ders kitaplarının parşömen ve kâğıt yerine mermer sütunlara kazınarak dersliklere dikilmesi', 'El yazması çoğaltımının yasaklanarak her şehirde tek bir ortak zincirli kitabın bırakılması'], '12.-13. yüzyıllarda Paris, Bologna, Oxford gibi üniversite kentlerinde "stationarius" ve "pecia" sistemiyle onaylı ders metinleri parça parça kiralanıp laik kâtiplerce çoğaltılmış; İslam dünyasında ise verrâk çarşıları bu işlevi görmüştür.'),
  ('Antik Yunan\'dan Orta Çağ\'a uzanan süreçte İskenderiye ve Bergama kütüphanelerindeki binlerce rulonun günümüze ulaşamamasının yangın ve savaşlar dışındaki en sessiz ama belirleyici nedeni nedir?', 'Belirli bir dönemde ilgi görmeyen veya eski yazı stiliyle yazılmış eserlerin yeni malzeme/formlara (rulodan kodekse, papirüsten parşömene) kopyalanmayarak doğal çürümeye terk edilmesi', ['Tüm antik bilginlerin öldüklerinde kendi yazdıkları kitapları mezarlarına koydurup yaktırmaları', 'Papirüs ve parşömen yapraklarının yirmi yıl içinde kendiliğinden toza dönüşen kimyasal yapıya sahip olması', 'Gutenberg\'in matbaayı kurduğunda Avrupa\'daki tüm el yazmalarını toplatıp geri dönüşümde eritmesi'], 'Kitap tarihinde "darboğaz" etkisi denilen süreçte; papirüs rulodan parşömen kodekse (MS 3.-5. yy) ve majüskülden minüskül yazıya (MS 9. yy) geçilirken yeniden kopyalanmaya değer görülmeyen eserler zamanla çürüyüp kaybolmuştur.'),
  ('Sümer çivi yazısından Gutenberg matbaasına uzanan beş bin yıllık yazı ve kitap tarihi bir bütün olarak değerlendirildiğinde, bilgi teknolojisindeki her büyük kırılmanın ortak toplumsal sonucu nedir?', 'Bilginin kayıt maliyetini düşürüp erişim hızını artırarak okuryazarlığı dar bir seçkinler zümresinden daha geniş toplum kesimlerine yayması', ['Sözlü iletişimi ve insan hafızasını tamamen ortadan kaldırarak konuşma dillerinin sayısını bire indirmesi', 'Devlet bürokrasisini ve hukuk sistemlerini zayıflatarak yazılı anlaşmalara duyulan güveni azaltması', 'Eski döneme ait tüm edebi ve dini mirası geçersiz kılarak kültürel sürekliliği tamamen koparması'], 'Çivi yazısından 22 harfli Fenike alfabesine, pahalı papirüs/parşömenden Semerkant kâğıdına, rulodan kodekse ve el yazmasından matbaaya geçişlerin tamamı bilgiyi ucuzlatmış, taşınabilir kılmış ve demokratikleştirmiştir.'),
  ('MS 2. yüzyılda Bergama\'da yetişen ve Roma\'da hekimlik yapan Galenos\'un tıbbi eserlerinin hem parşömen kodekslere hem de daha sonra Bağdat\'ta kâğıt nüshalara çevrilerek korunması hangi tarihsel gerçeği örnekler?', 'Antik Yunan-Roma bilimsel mirasının parşömen ve Semerkant/Bağdat kâğıdı köprüsüyle İslam dünyasında korunup Avrupa\'ya yeniden aktarıldığını', ['Tıp kitaplarının Antik Çağ\'dan beri yalnızca kil tabletler üzerinde yazılıp hiç değiştirilmediğini', 'Bergama Kütüphanesi\'ndeki tüm kitapların doğrudan Gutenberg\'in Mainz\'daki atölyesine taşındığını', 'Çeviri faaliyetlerinin kitap malzemesi değiştiğinde bilimsel içeriği tamamen yok ettiğini'], 'Bergamalı Galenos, Hipokrat ve Aristoteles gibi bilginlerin eserleri papirüsten parşömen kodekslere, 8.-10. yüzyıllarda ise Bağdat\'ta kâğıt üzerine Arapçaya çevrilerek yok olmaktan kurtulmuş ve Rönesans\'ı beslemiştir.'),
  ('Asurbanipal Kütüphanesi\'ndeki kil tabletlerin sonunda yer alan ve eserin adını, ait olduğu seriyi ve kraliyet mülkiyet mührünü içeren kayıt bölümüne ne ad verilir?', 'Kolofon', ['Palimpsest', 'Kodeks', 'Papirüs'], 'Antik tablet ve el yazmalarının sonundaki künye, kâtip ve mülkiyet bilgilerini içeren ketebe kaydına kolofon denir.'),
  ('19. yüzyılın ortalarında Koyuncuk Höyüğü\'nde kazı yaparak Asurbanipal Kütüphanesi\'nin binlerce tabletini gün yüzüne çıkaran araştırmacılar kimlerdir?', 'Austen Henry Layard ve Hormuzd Rassam', ['Heinrich Schliemann ve Wilhelm Dörpfeld', 'Howard Carter ve Lord Carnarvon', 'Arthur Evans ve Michael Ventris'], 'Koyuncuk (Ninova) kazılarında Asurbanipal Kütüphanesi\'ni Austen Henry Layard ve yerel asistanı Hormuzd Rassam keşfetmiştir.'),
  ('Asurbanipal Kütüphanesi\'nde Gılgamış Destanı dışında bulunan ve Babil\'in yaratılış mitini anlatan ünlü destan hangisidir?', 'Enuma Eliş', ['İlyada ve Odysseia', 'Mahabharata', 'Yaratılış ve Türeyiş'], 'Yedi tabletten oluşan Babil yaratılış destanı Enuma Eliş\'in temel nüshaları Asurbanipal Kütüphanesi\'nden çıkarılmıştır.'),
  ('İskenderiye Kütüphanesi\'ndeki yüz yirmi ciltlik "Pinakes" adlı eseri hazırlayarak tarihin ilk sistematik kütüphane kataloğunu oluşturan bilgin kimdir?', 'Kallimakhos', ['Aristarkhos', 'Öklid', 'Apollonios'], 'Şair ve bilgin Kallimakhos, eserleri konularına ve yazarlarına göre sınıflandıran Pinakes kataloğunu hazırlamıştır.'),
  ('İskenderiye Kütüphanesi\'nin kuruluşunda I. Ptolemaios Soter\'e danışmanlık yapan Atinalı devlet adamı ve Aristotelesçi filozof kimdir?', 'Phaleronlu Demetrios', ['Rodoslu Andronikos', 'Kıbrıslı Zenon', 'Sisamlı Aristarkhos'], 'Aristoteles\'in Lykeion okulunun birikimini Mısır\'a taşıyan Phaleronlu Demetrios, Mouseion ve kütüphanenin kuruluşunu planlamıştır.'),
  ('İskenderiye Kütüphanesi\'nin yok oluşu hakkında modern tarihçilerin ulaştığı en tutarlı değerlendirme aşağıdakilerden hangisidir?', 'Tek bir yangınla değil, Sezar\'ın kuşatması ve sonraki yüzyıllardaki iç çatışmalarla aşamalı olarak yok olmuştur', ['MÖ 331 yılında Büyük İskender\'in Mısır seferindeki deniz savaşı sırasında tamamen yanmıştır', 'Yalnızca MS 642 yılında Amr bin As komutasındaki ordunun hamamlarda yakmasıyla ortadan kalkmıştır', 'Büyük bir deprem ve tsunami sonucunda tüm papirüslerle birlikte Akdeniz sularına gömülmüştür'], 'Tarihsel kaynaklar kütüphanenin MÖ 48 Sezar kuşatması, MS 3. yüzyıl Aurelianus savaşları ve 391 Serapeum yıkımı gibi süreçlerle kademeli olarak eridiğini gösterir.'),
  ('Antik kaynaklarda Marcus Antonius\'un Bergama Kütüphanesi\'ne ait iki yüz bin ruloyu kime hediye etmek amacıyla İskenderiye\'ye taşıdığı rivayet edilir?', 'VII. Kleopatra\'ya', ['Octavianus Augustus\'a', 'Julius Caesar\'a', 'Livia Drusilla\'ya'], 'Plutarkhos\'un aktardığı ünlü rivayete göre Marcus Antonius, Sezar dönemindeki kayıpları telafi etmek için Bergama koleksiyonunu Kleopatra\'ya bağışlamıştır.'),
  ('Parşömenin yaygınlaşması Antik Çağ\'ın sonlarında kitap biçiminde hangi köklü dönüşüme zemin hazırlamıştır?', 'Rulo biçiminden katlanıp dikilen yapraklardan oluşan kodeks formuna geçilmesine', ['El yazmacılığının bırakılıp hareketli metal harfli baskı tekniğine geçilmesine', 'Metinlerin her iki yüzünün kullanılmasının tamamen yasaklanmasına', 'Kitapların yalnızca rahipler tarafından okunabilen şifreli alfabelerle yazılmasına'], 'Papirüse göre katlanmaya ve çift taraflı yazıma çok uygun olan parşömen, bugünkü kitap biçiminin atası olan kodeksin (codex) doğuşunu sağlamıştır.'),
  ('Bergama dilbilim okulunun başında bulunan, İskenderiye okuluyla dil kuralları üzerine tartışan ve Roma\'da edebiyat araştırmalarını başlatan bilgin kimdir?', 'Malloslu Krates', ['Samosatalı Lukianos', 'Amasyalı Strabon', 'İznikli Hipparkhos'], 'Stoacı dilbilimci Malloslu Krates, Bergama Kütüphanesi çevresinde anomali kuramını savunmuş ve elçi olarak gittiği Roma\'da edebiyat dersleri vermiştir.'),
  ('Beytülhikme\'de matematik ve mekanik alanında çalışan, "Kitâbü\'l-Hiyel" adlı otomatik düzenekler kitabını kaleme alan üç kardeş kimdir?', 'Benû Musa Kardeşler', ['İhvân-ı Safâ', 'Bermekî Kardeşler', 'Nevbahtî Ailesi'], 'Muhammed, Ahmed ve Hasan adlı Benû Musa Kardeşler; Beytülhikme\'de astronomi gözlemleri yapmış, çevirmenleri desteklemiş ve mekanik düzenekler tasarlamıştır.'),
  ('Antik Mezopotamya yıldız inançlarını sürdüren Harran ekolünden gelerek Bağdat\'ta Öklid ve Arşimet çevirileri yapan ünlü matematikçi kimdir?', 'Sabit bin Kurra', ['Battani', 'Fergânî', 'Zerkâlî'], 'Harranlı Sabiî alim Sabit bin Kurra, Benû Musa Kardeşlerin davetiyle Bağdat\'a gelerek matematik ve astronomi tercümelerinde çığır açmıştır.'),
  ('Hint astronomi klasiği "Siddhanta"nın "Sindhind" adıyla Arapçaya çevrilmesini sağlayan erken dönem Abbasi astronomu kimdir?', 'Muhammed bin İbrahim el-Fezârî', ['Nasîrüddin Tûsî', 'Ali Kuşçu', 'Kâtip Çelebi'], 'Halife Mansur döneminde Bağdat\'a gelen Hintli heyetin getirdiği Siddhanta metnini Fezârî Arapçaya çevirerek İslam astronomisini başlatmıştır.'),
  ('Beytülhikme\'deki çeviri hareketinin salt bir taklit faaliyeti olarak kalmayıp özgün bilimsel üretime dönüştüğünü hangi gelişme en iyi kanıtlar?', 'Batlamyus\'un astronomi tablolarının Bağdat ve Şam gözlemevlerindeki yeni ölçümlerle düzeltilmesi', ['Yunanca el yazmalarının altın yaldızlı tezhiplerle süslenerek saray hazinesinde saklanması', 'Eski Yunan mitolojisindeki tanrı isimlerinin eksiksiz biçimde Arapça şiirlere uyarlanması', 'Çevrilen kitapların ağırlığınca altın ödenmesi geleneğinin tüm eyaletlerde zorunlu tutulması'], 'Şemmâsiye (Bağdat) ve Kasiyun (Şam) rasathanelerinde yapılan gözlemlerle Batlamyus verilerinin tashih edilmesi eleştirel ve deneysel bilimin kanıtıdır.'),
  ('Sasani İmparatorluğu döneminde İran\'da kurulan, tıp okulu ve kütüphanesiyle Beytülhikme\'ye doğrudan model ve kadro sağlayan şehir hangisidir?', 'Cündişapur', ['İsfahan', 'Nişabur', 'Şiraz'], 'Huzistan bölgesindeki Cündişapur tıp akademisi ve Buhtişû ailesi gibi hekimler, Bağdat\'taki bilim ve çeviri ortamının öncüsü olmuştur.'),
  ('Halife Memun\'un Sincar Ovası\'nda yer kürenin bir derecelik meridyen yayını ölçtürdüğü bilim heyetinde yer alan ünlü Türk asıllı astronom kimdir?', 'Fergânî', ['Kaşgarlı Mahmud', 'Yusuf Has Hacib', 'Ahmet Yesevi'], 'Batı\'da Alfraganus olarak tanınan Ferganalı astronom Ahmed bin Muhammed el-Fergânî, Memun dönemindeki meridyen ölçümü ve astronomi çalışmalarında yer almıştır.'),
  ('10. yüzyılda Bağdat\'ta yaşayan İbnü\'n-Nedîm\'in, çeviri hareketiyle oluşan tüm kitap ve yazar birikimini kayıt altına aldığı ünlü bibliyografik eseri hangisidir?', 'el-Fihrist', ['Keşfü\'z-Zünûn', 'Муkaddime', 'Tabakâtü\'l-Ümem'], 'Kitapçı ve hattat İbnü\'n-Nedîm\'in 987 civarında yazdığı el-Fihrist, Beytülhikme ve çeviri dönemi literatürünün en kapsamlı birincil kaynağıdır.'),
  ('990\'lı yıllarda Bağdat\'ta Büveyhî Veziri Sâbûr bin Erdeşîr tarafından Beytülhikme geleneğini sürdürmek üzere kurulan kütüphane ve bilim merkezi hangisidir?', 'Dârü\'l-İlm', ['Dârü\'ş-Şifâ', 'Rasad-ı Cedîd', 'Beytü\'l-Mâl'], 'Vezir Sâbûr bin Erdeşîr\'in Bağdat\'ın Kerh yakasında kurduğu Dârü\'l-İlm (Bilim Evi), on binden fazla eseri barındıran önemli bir araştırma kütüphanesiydi.'),
  ('Arapçaya çevrilmiş bilim ve felsefe mirasının 12. yüzyılda Latinceye aktarılarak Avrupa\'ya taşınmasında merkez rolü oynayan İspanya şehri hangisidir?', 'Toledo', ['Lizbon', 'Barselona', 'Valensiya'], 'Başpiskopos Raimundo ve Gerardus Cremonensis gibi isimlerin faaliyet yürüttüğü Toledo Tercüme Okulu, İslam bilim mirasını Latinceye aktarmıştır.'),
  ('Abbasi vezir ailesi Bermekîlerin Beytülhikme öncesi ve sırasındaki çeviri hareketine en önemli katkısı aşağıdakilerden hangisidir?', 'Fars, Hint ve Yunan eserlerinin tercümesini finanse edip Bağdat\'ta ilk kağıt fabrikasını kurmaları', ['Yalnızca askeri strateji kitaplarının Türkçeye çevrilmesini zorunlu kılmaları', 'Antik Mısır hiyerogliflerini çözerek papirüs ticaretini tekellerine almaları', 'Bağdat dışındaki tüm eyalet kütüphanelerini kapatarak kitapları sarayda toplamaları'], 'Yahya bin Halid el-Bermekî ve oğulları Hint hekimlerini Bağdat\'a davet etmiş, çevirileri desteklemiş ve Bağdat kağıt imalathanesine öncülük etmiştir.'),
  ('Bağdat Nizamiye Medresesi tamamlandığında 1067 yılında ilk başmüderris olarak görevlendirilen Şafiî fıkıh alimi kimdir?', 'Ebû İshak eş-Şîrâzî', ['Abdülkerim el-Kuşeyrî', 'Ebû Bekir el-Bâkıllânî', 'Ali bin Muhammed el-Mâverdî'], 'Bağdat Nizamiyesi\'nin açılışında müderrislik kürsüsü dönemin saygın Şafiî fakihi Ebû İshak eş-Şîrâzî için tahsis edilmiştir.'),
  ('Nişabur Nizamiye Medresesi\'nde yaklaşık otuz yıl başmüderrislik yapan ve Gazzâlî\'nin de hocası olan ünlü kelam ve fıkıh alimi kimdir?', 'İmâmü\'l-Harameyn el-Cüveynî', ['Ebü\'l-Hasan el-Eş\'arî', 'Ömer bin Abdülaziz', 'Abdülkâhir el-Cürcânî'], 'Mekke ve Medine\'de ders verdiği için İmâmü\'l-Harameyn lakabını alan Cüveynî, Nişabur Nizamiyesi\'nin en ünlü başmüderrisiydi.'),
  ('Nizamülmülk\'ün devlet yönetimi, eğitim ve kurumlar hakkındaki görüşlerini Sultan Melikşah\'a sunmak üzere Farsça kaleme aldığı ünlü eseri hangisidir?', 'Siyasetnâme', ['Kabusnâme', 'Kutadgu Bilig', 'Çehâr Makâle'], 'Asıl adı Siyerü\'l-Mülûk olan Siyasetnâme, Selçuklu devlet teşkilatı ve Nizamülmülk\'ün yönetim anlayışının temel kaynağıdır.'),
  ('Nizamiye Medreselerinde fıkıh eğitimi ağırlıklı olarak hangi mezhebin esaslarına göre düzenlenmiştir?', 'Şafiî mezhebi', ['Hanbelî mezhebi', 'Malikî mezhebi', 'Zeydî mezhebi'], 'Sultanlar Hanefî olmasına rağmen Vezir Nizamülmülk Şafiî olduğu için Nizamiye vakfiyelerinde müderrislerin Şafiî mezhebinden olması şart koşulmuştur.'),
  ('Nizamiye Medreseleri dışında Bağdat\'ta Sultan Melikşah\'ın maliye nazırı Tâcülmülk tarafından Hanefî fıkhı okutulmak üzere hangi medrese kurulmuştur?', 'Ebû Hanîfe Medresesi', ['Mustansıriyye Medresesi', 'Karatay Medresesi', 'Gök Medrese'], 'Şafiî ağırlıklı Nizamiye\'nin yanında Hanefî alim ve öğrencileri desteklemek amacıyla Bağdat\'ta İmam-ı Azam türbesi yanında Ebû Hanîfe Medresesi açılmıştır.'),
  ('Gazzâlî\'nin 1095 yılında Bağdat Nizamiye Medresesi\'ndeki parlak kariyerini bırakarak şehirden ayrılmasının temel nedeni nedir?', 'Hakikate yalnızca akıl ve resmi medrese ilimleriyle ulaşılamayacağını düşünerek manevi bir arayışa girmesi', ['Büyük Selçuklu Sultanı Alp Arslan tarafından görevden alınarak Semerkant\'a sürgün edilmesi', 'Haçlı ordularının Bağdat\'ı işgal ederek tüm medrese binalarını kiliseye çevirmesi', 'Matematik ve mantık ilimlerinin medrese müfredatında okutulmasının halifece yasaklanması'], 'Gazzâlî, "el-Münkız mine\'d-Dalâl" eserinde anlattığı fikrî ve ruhî bunalım sonucunda makam-mevkiyi terk edip tasavvufa yönelmiştir.'),
  ('İslam dünyasında Nizamiye Medreselerinden önce 10. ve 11. yüzyıllarda ilk medrese örneklerinin ortaya çıktığı coğrafi bölge neresidir?', 'Horasan ve Maveraünnehir', ['Endülüs ve Mağrib', 'Yemen ve Hicaz', 'Kırım ve Kafkasya'], 'Medrese kurumu Nizamiye\'den yaklaşık bir asır önce Nişabur, Beyhak, Merv ve Buhara gibi Horasan-Maveraünnehir şehirlerinde doğmuştur.'),
  ('Bağdat Nizamiye Medresesi kütüphanesini on binlerce cilt kitap vakfederek zenginleştiren ve 12. yüzyıl sonunda kurumu ihya eden Abbasi halifesi kimdir?', 'Nâsır-Lidînillâh', ['Harun Reşid', 'Mu\'tasım-Billâh', 'Mütevekkil-Alellâh'], 'Halife Nâsır-Lidînillâh 1193 yılında Bağdat Nizamiyesi\'ne yeni bir kütüphane binası yaptırmış ve saraydan binlerce değerli el yazması vakfetmiştir.'),
  ('Nizamiye Medreselerinin uzun vadede İslam bilim tarihindeki etkileri değerlendirildiğinde araştırmacıların sıklıkla dikkat çektiği sınırlılık nedir?', 'Naklî ve fıkhî ilimleri merkeze alırken doğa bilimleri ve felsefeye resmi müfredatta sınırlı yer vermesi', ['Yalnızca astronomi ve tıp okuttuğu için dinî ilimlerin tamamen unutulmasına yol açması', 'Kütüphanelerinde kitap bulundurulmasını yasaklayarak yalnızca ezbere dayalı sözlü geleneği sürdürmesi', 'Öğrencilerden çok yüksek kayıt ücretleri alarak yoksul halk çocuklarını eğitimden dışlaması'], 'Nizamiye müfredatı fıkıh, kelam ve Arap dili gibi dinî/hukukî bilimleri kurumsallaştırırken astronomi ve felsefe daha çok saray ve rasathane çevrelerinde gelişmiştir.'),
  ('Bağdat Nizamiye Medresesi\'nde dil ve edebiyat müderrisliği yapan, "Şerhu\'l-Hamâse" gibi eserleriyle tanınan ünlü dil alimi kimdir?', 'Hatîb et-Tebrîzî', ['Sîbeveyhî', 'Halil bin Ahmed', 'İbn Manzûr'], 'Ebû Zekeriyyâ Yahya bin Ali et-Tebrîzî (Hatîb et-Tebrîzî), Bağdat Nizamiye Medresesi\'nde uzun yıllar edebiyat okutmuş ve kütüphane nazırlığı yapmıştır.'),
  ('Eyyûbîler ve Memlükler döneminde Nizamiye modeli örnek alınarak Kahire ve Şam\'da medreselerin hızla yayılmasını sağlayan ünlü hükümdar kimdir?', 'Selahaddin Eyyûbî', ['Baybars', 'Kansu Gavri', 'Tolunoğlu Ahmed'], 'Selahaddin Eyyûbî, Fatımî yönetimine son verdikten sonra Sünni eğitimi güçlendirmek için Kahire ve Kudüs\'te Nizamiye tipinde çok sayıda medrese açmıştır.'),
  ('Beytülhikme ile Nizamiye Medreseleri karşılaştırıldığında iki kurum arasındaki en belirgin yapısal fark aşağıdakilerden hangisidir?', 'Beytülhikme\'nin çeviri ve araştırma akademisi, Nizamiye\'nin ise standart müfredatlı yükseköğretim okulu olması', ['Beytülhikme\'nin yalnızca dinî hukuk öğretmesi, Nizamiye\'nin ise sadece Yunanca tıp çevirisi yapması', 'Beytülhikme\'nin vakıflarla yönetilmesi, Nizamiye\'nin ise tamamen öğrenci harçlarıyla finanse edilmesi', 'Beytülhikme\'nin Anadolu\'da kurulması, Nizamiye\'nin ise Endülüs\'te faaliyet göstermesi'], 'Beytülhikme tercüme, astronomi gözlemi ve telif odaklı bir saray akademisiyken; Nizamiye fıkıh ve bürokrasi odaklı örgün medrese sistemidir.'),
  ('Uluğ Bey\'in davetiyle Kâşân\'dan Semerkant\'a gelen, ondalık kesirleri sistemleştiren ve pi sayısını virgülden sonra on altı basamak doğru hesaplayan alim kimdir?', 'Gıyâseddin Cemşîd el-Kâşî', ['Ömer Hayyam', 'Nasîrüddin Tûsî', 'Kemâleddin el-Fârisî'], '"Miftâhu\'l-Hisâb" yazarı Gıyâseddin Cemşîd el-Kâşî, Semerkant Rasathanesi\'nin kuruluşunda ve hesaplamalarında başrol oynamıştır.'),
  ('Semerkant\'taki Uluğ Bey Medresesi\'nin giriş taç kapısına kazınan ve kurumun ruhunu yansıtan ünlü hadis metni neyi emretmektedir?', 'İlim öğrenmenin her Müslüman erkek ve kadına farz olduğunu', ['Yalnızca savaş ganimetleriyle devlet hazinesinin doldurulması gerektiğini', 'Ticaret kervanlarından alınan vergilerin yarı yarıya indirilmesini', 'Yıldızların hareketlerine bakarak gelecekten haber verilmesini'], 'Uluğ Bey, klasik medreselerden farklı olarak taç kapıya "İlim talep etmek her Müslüman erkek ve kadın üzerine farzdır" hadisini yazdırmıştır.'),
  ('Uluğ Bey Rasathanesi\'nde güneş ve gezegenlerin meridyen geçiş yüksekliklerini çok hassas ölçmek için kayaya oyularak inşa edilen dev gözlem aleti hangisidir?', 'Fahri Sekstantı', ['Usturlab-ı Zerkâlî', 'Pusula-i Kıble', 'Su Saati'], 'Yarıçapı yaklaşık kırk metre olan dev meridyen yayı (Suds-i Fahrî / Fahri Sekstantı), saniye mertebesinde açısal ölçüm yapılmasına imkan tanımıştır.'),
  ('Uluğ Bey\'in Semerkant dışında 1417 yılında Buhara\'da inşa ettirdiği medrese, Orta Asya mimarisinde hangi ikili yerleşim düzeninin erken örneklerindendir?', 'Karşılıklı iki anıtsal yapının cephe cepheye baktığı "koş" düzeninin', ['Tek kubbeli yuvarlak göçebe çadırı biçimindeki kümbet planının', 'Deniz kıyısına kazıklar üzerine oturtulan ahşap yalı medreselerinin', 'Yer altına yedi kat halinde kazılan kaya oyma manastır şemasının'], 'Orta Asya\'da iki yapının aynı eksende cephe cepheye yerleştirildiği "koş" (çift) mimari düzeni Uluğ Bey\'in Buhara ve Semerkant yapılarında görülür.'),
  ('Fatih Kanunnâmesi\'nde ve Sahn-ı Seman müfredatının düzenlenmesinde Fatih Sultan Mehmed\'e yardımcı olan iki büyük alim kimdir?', 'Ali Kuşçu ve Molla Hüsrev', ['Ebussuud Efendi ve Kemalpaşazâde', 'Pîrî Reis ve Matrakçı Nasuh', 'Naima Efendi ve Evliya Çelebi'], 'Rivayet ve kaynaklara göre Sahn-ı Seman\'ın ders programı ve derecelendirilmesinde Molla Hüsrev ve Ali Kuşçu\'nun önemli katkıları olmuştur.'),
  ('Osmanlı medrese hiyerarşisinde müderrislerin dereceleri aldıkları günlük ücrete (yevmiye) göre nasıl adlandırılırdı?', 'Yirmili, Otuzlu, Kırklı, Hariç, Dahil ve Sahn', ['Çırak, Kalfa, Usta ve Ahi Baba', 'Mülazım, Yüzbaşı, Binbaşı ve Sancakbeyi', 'Mübtedi, Mutavassıt, Müntehi ve Halife'], 'Osmanlı ilmiye teşkilatında medreseler müderrisin günlük akçe yevmiyesine göre Haşiye-i Tecrid (Yirmili), Miftah (Otuzlu), Kırklı, Hariç, Dahil ve Sahn olarak sıralanırdı.'),
  ('Fatih Külliyesi\'nde Sahn-ı Seman ve Tetimme medreselerinin yanı sıra hastaların tedavi edildiği ve uygulamalı tıp eğitimi verilen bölüm hangisidir?', 'Fatih Dârüşşifâsı', ['Haseki Bîmarhânesi', 'Gevher Nesibe Tıbbiyesi', 'Amasya Dârüşşifâsı'], 'Fatih Külliyesi içinde yer alan Dârüşşifâ, hem hastane hizmeti vermiş hem de hekim adaylarının usta-çırak yöntemiyle yetiştiği bir merkez olmuştur.'),
  ('Sahn-ı Seman Medreselerinde kelam derslerinde temel metin olarak okutulan "Şerhu\'l-Mevâkıf" adlı eserin yazarı olan ünlü alim kimdir?', 'Seyyid Şerîf Cürcânî', ['İbn Kemal', 'Taşköprîzâde', 'Kınalızâde Ali Efendi'], 'Adudüddin el-Îcî\'nin eserine Seyyid Şerîf Cürcânî\'nin yazdığı Şerhu\'l-Mevâkıf, Sahn-ı Seman kelam ve felsefi kelam müfredatının başyapıtıydı.'),
  ('Ali Kuşçu\'nun İstanbul\'a gelirken tamamlayıp Fatih Sultan Mehmed\'e sunduğu ve medreselerde ders kitabı olarak okutulan astronomi eseri hangisidir?', 'el-Fethiyye', ['Kitâb-ı Bahriye', 'Mir\'âtü\'l-Memâlik', 'Tuhfetü\'l-Kibâr'], 'Otlukbeli Zaferi sıralarında Fatih\'e ithaf edilen Arapça astronomi eseri "er-Risâletü\'l-Fethiyye" (el-Fethiyye), Osmanlı medreselerinde yüzyıllarca okutulmuştur.'),
  ('Süleymaniye Külliyesi\'nde Evvel, Sânî, Sâlis ve Râbi adlarıyla kurulan dört büyük medrese topluca hangi isimle anılmıştır?', 'Medâris-i Erbaa', ['Sahn-ı Seman', 'Enderun Odaları', 'Mekteb-i Sultani'], 'Süleymaniye Camii\'nin iki yanında yer alan Evvel, Sânî (Haliç tarafı da Sâlis ve Râbi) medreseleri "Dörtlü Medreseler" olarak matematik ve ilahiyat ağırlıklı eğitim vermiştir.'),
  ('Kanuni Sultan Süleyman\'ın vakfiyesini ve medrese kanunlarını düzenleyen, yaklaşık otuz yıl şeyhülislamlık yapan ünlü Osmanlı hukuk bilgini kimdir?', 'Ebussuud Efendi', ['Zenbilli Ali Efendi', 'Çivizâde Muhyiddin Efendi', 'Şeyhülislam Yahya Efendi'], 'Muhteşem Süleyman ve II. Selim dönemlerinin büyük şeyhülislamı Ebussuud Efendi, Süleymaniye\'nin hukuki ve ilmi çerçevesinde belirleyici olmuştur.'),
  ('Süleymaniye Medreselerine öğrenci hazırlamak üzere külliye bünyesinde kurulan orta-üst kademe medreseye ilmiye hiyerarşisinde ne ad verilmiştir?', 'Mûsıla-i Süleymaniye', ['Haşiye-i Tecrid', 'İbtidâ-i Hariç', 'Mekteb-i Rüşdiye'], '"Süleymaniye\'ye ulaştıran" anlamındaki Mûsıla-i Süleymaniye derecesi, Sahn-ı Seman ile Süleymaniye arasındaki geçiş basamağını oluşturmuştur.'),
  ('Kâtip Çelebi\'nin "üçgenin iç açılarının toplamını bilmeyen kadının miras ve arazi davasında doğru hüküm veremeyeceği" örneği neyi savunmaktadır?', 'Dinî ve hukukî ilimlerin doğru uygulanabilmesi için matematik ve hendese gibi aklî bilimlerin zorunlu olduğunu', ['Kadılık mesleğinin tamamen kaldırılarak tüm davaların mimarlara devredilmesi gerektiğini', 'Geometri kitaplarının yalnızca askeri kale inşaatlarında kullanılmasına izin verilmesini', 'Medreselerde fıkıh derslerinin tamamen iptal edilerek sadece Öklid geometrisi okutulmasını'], 'Kâtip Çelebi, şer\'î hukukun (feraiz, arazi ölçümü, kıble ve vakit tayini) dahi riyazî ilimler olmadan eksik kalacağını kanıtlamak için bu analizi yapmıştır.'),
  ('16. yüzyıl sonunda III. Murad döneminde Tophane sırtlarında İstanbul Rasathanesi\'ni kurarak Uluğ Bey\'in cetvellerini güncelleyen Osmanlı astronomu kimdir?', 'Takiyüddin er-Râsıd', ['Ali Macar Reis', 'Sabuncuoğlu Şerefeddin', 'Bursalı Kadızâde'], 'Müneccimbaşı Takiyüddin, 1577\'de kurulan İstanbul Rasathanesi\'nde mekanik saatler ve dev gözlem aletleri kullanarak Semerkant geleneğini sürdürmüştür.'),
  ('Osmanlı\'da ilk bağımsız binaya sahip vakıf kütüphanesi 1678 yılında hangi devlet adamı adına Çemberlitaş yakınlarında inşa edilmiştir?', 'Köprülü Fazıl Ahmed Paşa', ['Sokullu Mehmed Paşa', 'Damat İbrahim Paşa', 'Merzifonlu Kara Mustafa Paşa'], 'Daha önce cami ve medrese odalarında bulunan kütüphanelerden farklı olarak ilk müstakil kütüphane binası Köprülü Kütüphanesi\'dir.'),
  ('16. yüzyılda Osmanlı alimlerinin ve müderrislerinin biyografilerini "eş-Şekâiku\'n-Nu\'mâniyye" adlı ünlü eserinde toplayan bilim tarihçisi kimdir?', 'Taşköprîzâde Ahmed Efendi', ['Mustafa Âlî', 'Peçevî İbrahim Efendi', 'Koçi Bey'], 'Taşköprîzâde\'nin "eş-Şekâiku\'n-Nu\'mâniyye fî Ulemâi\'d-Devleti\'l-Osmâniyye" eseri, kuruluşundan Kanuni devrine kadar Osmanlı medrese ve ulema tarihinin ana kaynağıdır.'),
  ('İbrahim Müteferrika\'nın matbaanın faydalarını anlatmak üzere Sadrazam Damat İbrahim Paşa\'ya sunduğu ünlü layihanın (raporun) adı nedir?', 'Vesîletü\'t-Tıbâa', ['Usûlü\'l-Hikem fî Nizâmi\'l-Ümem', 'Sefâretnâme-i Fransa', 'Risâle-i İslâmiyye'], '"Basımcılığın Araçları/Faydaları" anlamına gelen Vesîletü\'t-Tıbâa (1726), Müteferrika\'nın matbaanın gerekliliğini on maddede savunduğu tarihi metindir.'),
  ('İbrahim Müteferrika\'nın 1745\'teki vefatına kadar kendi matbaasında bastığı toplam kitap (başlık) sayısı kaçtır?', 'On yedi eser', ['Yüz elli eser', 'Beş yüz eser', 'Yalnızca üç eser'], '1729-1742 yılları arasında Müteferrika Matbaası\'nda yirmi dört cilt halinde toplam on yedi farklı eser (yaklaşık on iki bin nüsha) basılmıştır.'),
  ('Müteferrika Matbaası\'nda basılan ve içinde Amerika kıtasının keşfini anlatan "Târîh-i Hind-i Garbî" adlı eser hangi alanda Osmanlı okurunu bilgilendirmiştir?', 'Yeni Dünya\'nın coğrafyası, bitki örtüsü ve deniz keşifleri hakkında', ['Orta Asya Türk boylarının İslamiyet öncesi destanları hakkında', 'Antik Mısır piramitlerinin mimari hesaplamaları hakkında', 'Buharlı lokomotiflerin ve demiryollarının çalışma ilkeleri hakkında'], 'Resimli olarak 1730\'da Müteferrika tarafından basılan Târîh-i Hind-i Garbî (Batı Hint Tarihi), Kristof Kolomb ve sonrası Amerika keşiflerini anlatan önemli bir coğrafya-tarih eseridir.'),
  ('Lale Devri\'nde Sadrazam Damat İbrahim Paşa tarafından Doğu ve Batı dillerindeki önemli tarih, felsefe ve bilim eserlerini Türkçeye çevirmek üzere kurulan kurum nedir?', 'Tercüme Heyeti', ['Encümen-i Dâniş', 'Beytülhikme', 'Tercüme Odası'], 'Damat İbrahim Paşa 1720\'lerde Yanyalı Esad Efendi, Nedim ve Koca Ragıp gibi alimlerden oluşan otuz kişilik bir tercüme heyeti kurdurmuştur.'),
  ('Lale Devri tercüme hareketlerinde Aristoteles\'in "Fizik" kitabını doğrudan Yunancadan Arapçaya çevirerek "Muallim-i Sâlis" unvanıyla anılan Osmanlı alimi kimdir?', 'Yanyalı Esad Efendi', ['Gelenbevî İsmail Efendi', 'Erzurumlu İbrahim Hakkı', 'Kethüdazâde Mehmed Arif'], 'İyi derecede Yunanca ve Latince bilen müderris Yanyalı Esad Efendi, Lale Devri tercüme heyetlerinde yer almış ve Aristo şerhlerini Yunancadan çevirmiştir.'),
  ('Müteferrika Matbaası\'nda basılan Türkçe öğrenmek isteyen Avrupalılara yönelik "Grammaire Turque" (1730) adlı eser hangi alfabeyi de içermesiyle dikkat çeker?', 'Osmanlı matbaasında Arap harfleriyle birlikte Latin harflerinin de kullanıldığı ilk çift dilli dilbilgisi kitabı olmasıyla', ['Tamamı Çin ideogramlarıyla basılan ilk diplomasi sözlüğü olmasıyla', 'Çivi yazısı ve hiyeroglif sembollerini öğreten ilk arkeoloji kitabı olmasıyla', 'Kiril alfabesiyle basılmış ilk Rusça-Türkçe ticaret rehberi olmasıyla'], 'Cizvit rahibi Jean-Baptiste Holdermann tarafından hazırlanan Grammaire Turque, Müteferrika\'nın Fransa\'dan getirttiği Latin harfleriyle Arap harflerini bir arada bastığı eserdir.'),
  ('Avrupa\'da Gutenberg matbaasının yol açtığı hızlı okuryazarlık patlamasının 18. yüzyılda Müteferrika Matbaası sonrasında Osmanlı\'da aynı hızla görülmemesinin temel nedeni nedir?', 'Okuryazar kitlenin sınırlı kalması, basım maliyetlerinin yüksekliği ve el yazması kültürünün toplumsal saygınlığını koruması', ['Müteferrika\'nın bastığı kitapların okunmasının padişah fermanıyla halka yasaklanması', 'Matbaada kullanılan mürekkebin birkaç ay içinde kağıt üzerinden tamamen uçup silinmesi', 'Basılan tüm kitapların iç piyasada satılmayıp doğrudan İran ve Hindistan\'a ihraç edilmesi'], '18. yüzyılda henüz yaygın halk mektepleri ve gazete kültürü oluşmadığından talep sınırlı kalmış, matbaa asıl kitlesel etkisini 19. yüzyıl Tanzimat döneminde göstermiştir.'),
  ('Müteferrika\'nın ölümünden ve kesintili dönemlerden sonra III. Selim zamanında Üsküdar\'da devlet eliyle kurulan yeni matbaanın adı nedir?', 'Dârü\'t-Tıbâati\'l-Âmire', ['Matbaa-i Ebüzziya', 'Takvimhâne-i Âmire', 'Tercüme-i Fünûn'], 'Nizam-ı Cedid ıslahatları çerçevesinde Mühendishane ve ardından Üsküdar\'da kurulan Dârü\'t-Tıbâati\'l-Âmire, Osmanlı devlet matbaacılığını kurumsallaştırmıştır.'),
  ('Müteferrika Matbaası\'nda mıknatısın özellikleri ve pusula kullanımı üzerine 1732 yılında basılan fen bilimleri eseri hangisidir?', 'Füyûzât-ı Mıknatîsiyye', ['Kitâbü\'l-Menâzır', 'Kânûnçe fi\'t-Tıb', 'Mîzânü\'l-Hak'], 'İbrahim Müteferrika\'nın Batı kaynaklarından derleyip çevirerek bastığı Füyûzât-ı Mıknatîsiyye, mıknatıs, pusula sapması ve enlem-boylam bulma konularını işler.'),
  ('Beytülhikme (9. yy), Toledo Tercüme Okulu (12. yy) ve Lale Devri Tercüme Heyeti (18. yy) birlikte düşünüldüğünde bilim tarihi açısından hangi sonuca ulaşılır?', 'Bilimsel birikimin tek bir medeniyetin tekelinde olmayıp çeviri hareketleriyle kültürler arasında el değiştirerek geliştiğine', ['Çeviri yapan toplumların özgün düşünce üretemeyip kısa sürede tarih sahnesinden silindiğine', 'Felsefe ve astronomi eserlerinin yalnızca savaş ganimeti olarak ele geçirildiğinde anlaşılabildiğine', 'Tarih boyunca tüm çeviri hareketlerinin tek bir ortak yapay dil üzerinden yürütüldüğüne'], 'Yunan-Hint-İran mirası Arapçaya (Beytülhikme), İslam mirası Latinceye (Toledo) ve modern Avrupa mirası Osmanlı Türkçesine aktarılarak evrensel bilim zinciri kurulmuştur.'),
  ('Fatih Sultan Mehmed\'in Topkapı Sarayı\'ndaki özel kütüphanesinde Türkçe, Arapça ve Farsça eserlerin yanı sıra hangi dillerde bilimsel el yazmaları bulunmaktaydı?', 'Yunanca ve Latince', ['Japonca ve Korece', 'İzlandaca ve Fince', 'Aztek ve Maya dilleri'], 'Fatih\'in saray kütüphanesinde Batlamyus\'un Coğrafya\'sı (Geographike Hyphegesis) ve Homeros\'un İlyada\'sı dahil çok sayıda Yunanca ve Latince yazma bulunuyordu.'),
  ('Bir tarihçinin 16. yüzyıl Süleymaniye Medresesi müderris maaşlarını, öğrenci kontenjanlarını ve kütüphane kitap listesini birincil elden incelemesi için hangi belgeye başvurması gerekir?', 'Süleymaniye Külliyesi Vakfiyesi\'ne', ['Yirmisekiz Mehmed Çelebi Sefâretnâmesi\'ne', 'Pîrî Reis\'in Kitâb-ı Bahriye eserine', 'Nizamülmülk\'ün Siyasetnâme kitabına'], 'Osmanlı külliye ve medreselerinin kurumsal işleyişi, kadrosu, maaşları, okutulacak ders çerçevesi ve vakfedilen kitap listeleri kurucu "vakfiye" belgelerinde kayıtlıdır.'),
  ('1716 yılında Damat Ali Paşa (Şehit Ali Paşa) sonrası dönemde vakıf kütüphanelerinden dışarıya kitap çıkarılmasının sınırlandırılmasının temel gerekçesi nedir?', 'Nadir el yazmalarının kaybolmasını ve yurt dışındaki koleksiyonculara satılmasını önlemek', ['Halkın okuma yazma öğrenerek devlet memuru olmasını engellemek', 'Kütüphane binalarının yılın on bir ayı kapalı tutulmasını sağlamak', 'Kitap kapaklarındaki deri ciltlerin askeri koşum takımı yapımında kullanılması'], '18. yüzyılda Avrupalı şarkiyatçı ve elçilerin yoğun biçimde Doğu el yazmalarını toplayıp götürmesi üzerine Osmanlı vakıfları kitap koruması ve denetimini sıkılaştırmıştır.'),
  ('Kâtip Çelebi\'nin yirmi yıllık çalışmayla on beş bine yakın Arapça, Farsça ve Türkçe eseri alfabetik olarak tanıttığı dünyaca ünlü bibliyografya ansiklopedisi hangisidir?', 'Keşfü\'z-Zünûn', ['Mir\'âtü\'l-Kâinât', 'Tuhfetü\'l-Kibâr', 'Düstûru\'l-Amel'], 'Tam adı "Keşfü\'z-Zünûn an Esâmi\'l-Kütüb ve\'l-Fünûn" olan eser, yaklaşık üç yüz bilim dalını ve on beş bin kitabı tanıtan anıtsal bir kütüphanecilik ve bilim tarihi şaheseridir.'),
  ('Müteferrika Matbaası\'nda basılan on yedi eserin konularına bakıldığında (sözlük, tarih, coğrafya, harita, mıknatıs, askeri düzen) hangi yayın politikası görülür?', 'Devletin ve aydınların dünyayı tanıma, tarih bilinci kazanma ve pratik-bilimsel yenilenme ihtiyacına yanıt verme', ['Yalnızca divan şiiri antolojileri ve saray eğlencelerini anlatan surnâmeler yayımlama', 'Orta Çağ skolastik büyü ve fal metinlerini halka ucuz fiyata dağıtma', 'Sadece Arap yarımadasındaki göçebe kabilelerin soy kütüklerini kayıt altına alma'], 'Seçilen eserler; dil araçları (Vankulu, Ferheng-i Şuûrî), Osmanlı ve dünya tarihi/coğrafyası (Cihannümâ, Hind-i Garbî, Naîmâ) ile modern bilim/ıslahat (Usûlü\'l-Hikem, Füyûzât) odaklıdır.'),
  ('Papa IX. Gregorius tarafından 1231 yılında yayımlanan ve Paris Üniversitesi\'nin özerkliğini, grev hakkını ve müfredat yetkisini güvenceye alan papalık belgesi hangisidir?', 'Parens Scientiarum', ['Unam Sanctam Fermanı', 'Dictatus Papae Metni', 'In Coena Domini'], '"Bilimlerin Anası" anlamına gelen Parens Scientiarum, Paris Üniversitesi\'nin Magna Carta\'sı olarak anılır.'),
  ('Orta Çağ üniversitelerinde mezunlara verilen ve Avrupa\'daki herhangi bir üniversitede ders verme yetkisi sağlayan belgeye ne ad verilirdi?', 'Licentia ubique docendi', ['Disputatio ordinaria', 'Ratio studiorum belgesi', 'Privilegium fori beratı'], 'Papa veya imparator onaylı studium generale kurumlarının verdiği "her yerde ders verme ruhsatı" Licentia ubique docendi olarak adlandırılırdı.'),
  ('Selçuklu Veziri Nizamülmülk\'ün kurduğu Nizamiye Medreseleri ile Karaviyyin ve El-Ezher gibi erken dönem kurumları arasındaki kurumsal farklardan biri hangisidir?', 'Devlet destekli vakıf ağıyla standart müfredat ve yatılı burslu müderris-talebe sistemi kurması', ['Eğitim dili olarak Arapça yerine yalnızca Yunanca ve Latince metinleri zorunlu kılması', 'Dini ilimleri müfredattan çıkararak sadece denizcilik ve topçuluk eğitimi vermesi', 'Öğrencilerden yüksek kayıt ücretleri alarak müderris maaşlarını loncalara ödetmesi'], 'Nizamiye Medreseleri Sünni bürokrasi ve ilmiye sınıfı yetiştirmek üzere düzenli maaş, burs ve yatılı devlet himayesi sistemini kurumsallaştırmıştır.'),
  ('1224 yılında İmparator II. Friedrich tarafından kilise veya lonca girişimi olmaksızın doğrudan devlet fermanıyla bürokrat yetiştirmek üzere kurulan ilk Avrupa üniversitesi hangisidir?', 'Napoli Üniversitesi', ['Salamanca Üniversitesi', 'Coimbra Üniversitesi', 'Prag Üniversitesi'], 'Napoli Üniversitesi (Federico II), Sicilya Krallığı\'na hukukçu ve yönetici yetiştirmek amacıyla doğrudan seküler iktidar tarafından kurulmuştur.'),
  ('Orta Avrupa\'da (Alpler\'in kuzeyinde ve Ren\'in doğusunda) 1348 yılında İmparator IV. Karl tarafından kurulan ilk üniversite hangi şehirdedir?', 'Prag', ['Viyana', 'Heidelberg', 'Krakow'], 'Prag Karl Üniversitesi 1348\'de kurulmuş olup Orta Avrupa\'nın ilk üniversitesidir.'),
  ('İbn Haldun\'un 14. yüzyılda müderrislik yaptığı, aynı zamanda İbn Rüşd ve İbn Meymun gibi düşünürlerle de tarihsel bağları anılan Kuzey Afrika ilim merkezi hangisidir?', 'Karaviyyin ve El-Ezher çevreleri', ['Semerkant Uluğ Bey Medresesi', 'Edirne Üç Şerefeli Medresesi', 'İznik Orhaniyesi Medresesi'], 'İbn Haldun gençliğinde Fes\'te Karaviyyin çevresinde bulunmuş, ömrünün son döneminde ise Kahire\'de El-Ezher ve diğer medreselerde ders vermiştir.'),
  ('1810 yılında Wilhelm von Humboldt öncülüğünde kurulan Berlin Üniversitesi\'nin modern üniversite tarihine getirdiği en devrimci ilke aşağıdakilerden hangisidir?', 'Öğretim ile bilimsel araştırmanın birleştirilmesi ve akademik özgürlüğün esas alınması', ['Üniversitelerin yalnızca kilise din adamları tarafından denetlenmesinin yasalaşması', 'Tüm müfredatın antik Latince ezber metinleriyle sınırlandırılması', 'Öğrencilerin meslek loncaları aracılığıyla hocaları işten çıkarma yetkisinin canlandırılması'], 'Humboldt modeli (Lehrfreiheit ve Lernfreiheit), üniversiteyi sadece bilgi aktaran değil, araştırma yoluyla yeni bilgi üreten özerk kurum haline getirmiştir.'),
  ('II. Mahmud\'un 1839\'da Mekteb-i Tıbbiye-i Adliye-i Şahane\'nin açılış nutkunda eğitim dilinin geçici olarak Fransızca olmasını gerekçelendirirken vurguladığı temel hedef nedir?', 'Tıp biliminin Türkçe kaynaklara aktarılıp ileride tıp eğitiminin tamamen Türkçe yapılması', ['Osmanlı ordusundaki tüm subayların Fransa\'ya yerleşmesinin teşvik edilmesi', 'Arapça ve Farsça kelimelerin günlük konuşma dilinden derhal çıkarılması', 'Tıp fakültesi mezunlarının yalnızca Avrupa elçiliklerinde tercüman olarak çalıştırılması'], 'II. Mahmud konuşmasında Fransızcanın geçici bir araç olduğunu, asıl hedefin tıp kitaplarını Türkçeye kazandırıp eğitimi Türkçe yapmak olduğunu belirtmiştir.'),
  ('Osmanlı\'da sivil tıp eğitiminin gelişmesi ve tıp dilinin Türkçeleştirilmesi mücadelesi sonucunda 1867\'de Kırımlı Aziz Bey ve arkadaşlarının katkısıyla açılan kurum hangisidir?', 'Mekteb-i Tıbbiye-i Mülkiye', ['Tıbhane-i Amire', 'Cerrahhane-i Mamure', 'Gülhane Seririyat Hastanesi'], 'Cemiyet-i Tıbbiye-i Osmaniye\'nin çabalarıyla 1867\'de açılan Mekteb-i Tıbbiye-i Mülkiye\'de Türkçe tıp eğitimi başarıyla uygulanmıştır.'),
  ('1870\'li yıllarda Galatasaray Mekteb-i Sultanisi müdürlüğü yapan, kurumda hukuk, mühendislik ve edebiyat şubelerinden oluşan "Darülfünun-ı Sultani" girişimini yöneten devlet adamı ve tarihçi kimdir?', 'Sava Paşa ve Ali Suavi dönemleri', ['Ahmet Cevdet Paşa', 'Osman Hamdi Bey', 'Satı Bey'], 'Galatasaray Sultanisi\'nde Ali Suavi müdürlük yapmış, Sava Paşa döneminde ise okul bünyesinde üç fakülteli Darülfünun-ı Sultani açılmıştır.'),
  ('Darülfünun binasının inşası sürerken ders kitaplarını hazırlamak ve bilimsel çalışmaları yürütmek amacıyla 1851 yılında kurulan Osmanlı bilim akademisi hangisidir?', 'Encümen-i Daniş', ['Cemiyet-i İlmiye-i Osmaniye', 'Tarih-i Osmani Encümeni', 'Türk Bilgi Derneği'], '1851\'de Ahmet Cevdet Paşa ve Mustafa Reşid Paşa gibi isimlerin katkısıyla kurulan Encümen-i Daniş, Darülfünun\'un ders kitaplarını telif ve tercüme etmekle görevlendirilmişti.'),
  ('1870 yılında "Darülfünun-ı Osmani" adıyla açılan ikinci üniversite girişiminin ilk müdürü olan ve yaptığı vakumlu cam fanus (güvercin) deneyi gerekçe gösterilerek hedef alınan aydın kimdir?', 'Hoca Tahsin Efendi', ['Münif Paşa', 'Beşir Fuad', 'Şemseddin Sami'], 'Hoca Tahsin Efendi Darülfünun-ı Osmani\'nin müdürü olmuş; Cemaleddin Efgani\'nin konuşması ve deney tartışmaları sonrası kurum 1872-1873\'te kapanmıştır.'),
  ('1869 Maarif-i Umumiye Nizamnamesi\'ni hazırlayarak Osmanlı eğitim sisteminin ilk kez bütüncül bir yasal çerçeveye kavuşmasını sağlayan Maarif Nazırı kimdir?', 'Saffet Paşa', ['Kemal Efendi', 'Emrullah Efendi', 'Zühtü Paşa'], '1869 Maarif-i Umumiye Nizamnamesi Saffet Paşa\'nın nazırlığı döneminde yayımlanmış, ilk, orta ve yükseköğretimi (Darülfünun dahil) düzenlemiştir.'),
  ('II. Meşrutiyet Dönemi\'nde Maarif Nazırı Emrullah Efendi\'nin ortaya attığı "Tuba Ağacı Nazariyesi" eğitim reformlarında hangi önceliği savunmaktaydı?', 'Eğitimde yenileşmenin ilkokullardan değil, bilimsel kadroları yetiştirecek Darülfünun\'dan (yükseköğretimden) başlamasını', ['Tüm bütçenin yalnızca köy ilkokullarına ayrılıp üniversite ve liselerin geçici olarak kapatılmasını', 'Yabancı dil eğitiminin tamamen kaldırılarak yalnızca medrese icazetnamelerinin geçerli sayılmasını', 'Teknik ve mesleki okulların özel yabancı şirketlere devredilerek devletin eğitimden çekilmesini'], 'Kökleri yukarıda olan Tuba ağacı metaforunu kullanan Emrullah Efendi, iyi yetişmiş akademisyen ve öğretmen olmadan ilköğretimin düzelemeyeceğini savunmuştur.'),
  ('1914 yılında kadınlara yükseköğretim imkânı sağlamak amacıyla Darülfünun bünyesinde kurulan kuruma ne ad verilmiştir?', 'İnas Darülfünunu', ['Darülmuallimat-ı Aliye', 'Kandilli Kız Sultanisi', 'Tıbbiye-i Nisaiye'], '1914 yılında açılan İnas Darülfünunu, Osmanlı kadınlarının üniversite düzeyinde edebiyat, matematik ve tabii bilimler eğitimi almasını sağlamıştır.'),
  ('I. Dünya Savaşı yıllarında (1915-1918) Darülfünun\'u modernleştirmek ve enstitüler kurmak amacıyla Osmanlı hükümeti hangi ülkeden çok sayıda profesör getirtmiştir?', 'Almanya', ['İngiltere', 'İtalya', 'Rusya'], 'Maarif Nazırı Şükrü Bey döneminde müttefik Almanya\'dan yaklaşık yirmi profesör getirilerek Darülfünun\'da kürsü ve araştırma enstitüleri (Darülmesai) kurulmuştur.'),
  ('Kurtuluş Savaşı devam ederken 15-21 Temmuz 1921 tarihlerinde Mustafa Kemal Paşa\'nın açılış konuşmasını yaptığı ve milli eğitimin temellerinin tartışıldığı toplantı hangisidir?', 'Maarif Kongresi', ['İzmir İktisat Kongresi', 'Birinci Türk Tarih Kongresi', 'Birinci Heyet-i İlmiye Toplantısı'], 'Kütahya-Eskişehir Muharebeleri sürerken Ankara\'da toplanan Maarif Kongresi, yeni devletin milli ve çağdaş eğitim politikasının ilk adımı olmuştur.'),
  ('1924 yılında Türkiye\'ye davet edilerek Türk eğitim sistemi hakkında kapsamlı bir rapor hazırlayan Amerikalı ünlü eğitim felsefecisi kimdir?', 'John Dewey', ['Albert Malche', 'Alfred Kühne', 'Omer Buyse'], 'Pragmatist eğitimci John Dewey 1924\'te Türkiye\'yi ziyaret ederek öğretmen yetiştirme, köy okulları ve uygulamalı eğitim üzerine rapor sunmuştur.'),
  ('1923 İzmir İktisat Kongresi\'nde Latin harflerinin kabul edilmesi yönünde verilen önergenin Kazım Karabekir Paşa tarafından reddedilme gerekçelerinden biri ne olmuştur?', 'İslam dünyasıyla kültürel bağların kopacağı ve mevcut basılı mirasın okunamaz hale geleceği endişesi', ['Ülkedeki tüm vatandaşların zaten Latin alfabesini eksiksiz bildiğinin ileri sürülmesi', 'Matbaa makinelerinin yalnızca Kiril alfabesiyle baskı yapabildiğinin iddia edilmesi', 'Osmanlı Türkçesinde ünlü harflerin Latin alfabesinden çok daha fazla olduğunun savunulması'], '1923\'te ortam henüz olgunlaşmamışken Kazım Karabekir, İslam birliği algısı ve kütüphanelerdeki eserlerin durumu gibi çekincelerle öneriyi uygun bulmamıştır.'),
  ('Millet Mekteplerinden mezun olan halkın okuma alışkanlığını sürdürmesi amacıyla Maarif Vekaleti tarafından çıkarılan süreli yayın aşağıdakilerden hangisidir?', 'Halk Mecmuası', ['Sebilürreşad Dergisi', 'Servet-i Fünun Mecmuası', 'Kadro Dergisi'], 'Yeni harfleri öğrenen yurttaşların öğrendiklerini unutmaması ve sade metinlerle bilgilenmesi için 1929\'dan itibaren Halk Mecmuası yayımlanmıştır.'),
  ('1933 yılında Nazi Almanyası\'ndan kovulan Yahudi ve muhalif bilim insanlarının Türkiye\'deki üniversitelere kazandırılması için Zürih\'te kurulan örgütün başındaki profesör kimdir?', 'Philipp Schwartz', ['Wilhelm Röpke', 'Erich Auerbach', 'Fritz Arndt'], 'Patolog Prof. Philipp Schwartz liderliğindeki "Yurt Dışındaki Alman Bilim İnsanları Yardım Cemiyeti" (Notgemeinschaft), Ankara ile anlaşarak onlarca seçkin akademisyenin Türkiye\'ye gelmesini sağlamıştır.'),
  ('Birinci Türk Tarih Kongresi\'nde (1932) bazı Darülfünun müderrislerinin resmi tarih tezlerine mesafeli yaklaşması, Cumhuriyet yönetiminin Darülfünun\'a bakışını nasıl etkilemiştir?', 'Darülfünun\'un inkılaplara yeterince ayak uyduramadığı kanaatini güçlendirerek 1933 Üniversite Reformu\'nu hızlandırmıştır', ['Darülfünun\'un bütçesinin iki katına çıkarılarak tüm tarih araştırmalarının İstanbul\'a devredilmesini sağlamıştır', 'Türk Tarihi Tetkik Cemiyeti\'nin kapatılarak yetkilerinin Edebiyat Medresesi\'ne bırakılmasına yol açmıştır', 'Üniversite özerkliğinin anayasal güvenceye alınarak Maarif Vekaleti denetiminin tamamen kaldırılmasını sağlamıştır'], 'Harf İnkılabı, dil ve tarih tezleri karşısında Darülfünun kadrosunun pasif veya muhafazakâr bulunması, kurumun tasfiyesinde önemli bir siyasal etken olmuştur.'),
  ('1933\'te İstanbul Üniversitesi\'ne sığınmacı akademisyen olarak gelip Roman filolojisi kürsüsünü yöneten ve dünya edebiyat eleştirisinin başyapıtlarından "Mimesis"i İstanbul\'da yazan bilim insanı kimdir?', 'Erich Auerbach', ['Leo Spitzer', 'Hans Reichenbach', 'Ernst Hirsch'], 'Alman filolog Erich Auerbach, 1936-1947 yılları arasında İstanbul Üniversitesi\'nde görev yapmış ve ünlü eseri Mimesis\'i İstanbul\'da kaleme almıştır.'),
  ('1933 Üniversite Reformu ile İstanbul\'a gelen ve daha sonra Ankara\'da ticaret hukuku ile üniversite yasalarının hazırlanmasına büyük katkı sağlayan Alman hukuk profesörü kimdir?', 'Ernst Hirsch', ['Richard Honig', 'Alexander Rüstow', 'Alfred Isaac'], 'Prof. Dr. Ernst Hirsch, İstanbul ve Ankara Hukuk fakültelerinde görev yapmış, Türk Ticaret Kanunu ve 1946 Üniversiteler Kanunu\'nun mimarları arasında yer almıştır.'),
  ('11. yüzyıl sonlarında Bologna\'da Justinianus\'un Roma hukuku metinlerini satır arası ve kenar notlarıyla (glossa) şerh ederek hukuk okulunun kurucusu sayılan hukukçu kimdir?', 'Irnerius', ['Accursius', 'Bartolus de Saxoferrato', 'Gratianus'], '"Hukukun Kandili" (Lucerna Juris) lakaplı Irnerius, Bologna\'da Glossatorlar (Şerhçiler) okulunu başlatarak üniversitenin doğuşuna öncülük etmiştir.'),
  ('12. yüzyıl ortalarında Bologna\'da kilise hukukunu sistemleştiren "Decretum" adlı eseri yazarak kanonik hukuk biliminin kurucusu kabul edilen din adamı kimdir?', 'Gratianus', ['Petrus Lombardus', 'Anselmus', 'Büyük Albertus'], 'Keşiş Gratianus\'un derlediği Decretum Gratiani, Orta Çağ üniversitelerindeki kilise (kanonik) hukuku fakültelerinin temel ders kitabı olmuştur.'),
  ('Orta Çağ kentlerinde yerel esnaf-halk ile üniversite mensupları arasında sıkça patlak veren "Town and Gown" (Kasaba ve Cübbe) çatışmalarının başlıca ekonomik ve hukuki nedeni neydi?', 'Üniversite mensuplarının sivil mahkemelerden muaf tutulması ve kira-gıda fiyatları üzerindeki anlaşmazlıklar', ['Öğrencilerin yerel katedrallerdeki tüm dini ayinleri silah zoruyla yasaklamaya çalışması', 'Kasaba halkının üniversitedeki Latince felsefe derslerine ücretsiz girmek için ayaklanması', 'Derebeylerin tüm esnaf loncalarını kapatıp dükkanları zorla ilahiyat profesörlerine dağıtması'], 'Akademisyen ve öğrencilerin ruhban statüsüyle yerel mahkemelerden muaf olması (privilegium fori) ve fahiş kira/şarap fiyatları kanlı çatışmalara yol açmıştır.'),
  ('Paris Üniversitesi\'nde 12. yüzyıl başlarında "Sic et Non" (Evet ve Hayır) adlı eseriyle diyalektik sorgulama yöntemini geliştirerek binlerce öğrenciyi Paris\'e çeken düşünür kimdir?', 'Pierre Abelard', ['Clairvauxlu Bernard', 'Salisburyli John', 'Ockhamlı William'], 'Pierre Abelard, otoritelerin çelişkili sözlerini mantık süzgecinden geçiren yöntemiyle Paris\'in bir üniversite merkezine dönüşmesinde kilit rol oynamıştır.'),
  ('Oxford Üniversitesi\'nde 13. yüzyılda Robert Grosseteste\'nin izinden giderek optik, matematik ve deneysel bilim yöntemini savunan Fransisken bilgin kimdir?', 'Roger Bacon', ['Thomas Bradwardine', 'John Wycliffe', 'al-Kindi'], '"Doctor Mirabilis" unvanlı Oxfordlu bilgin Roger Bacon, Orta Çağ\'da gözlem ve deneyin bilimsel bilgideki önemini vurgulamıştır.'),
  ('Orta Çağ Batı üniversitelerindeki "kurumsal tüzel kişilik" (universitas) diploması ile klasik İslam medreselerindeki "icazet" sistemi arasındaki temel yapısal fark nedir?', 'Batı\'da diplomanın kurum adına verilmesi, medresede ise icazetin kurumsal tüzel kişilikten ziyade müderrisin şahsi otoritesiyle verilmesi', ['Medreselerde eğitimin tamamen ücretli olması, Avrupa üniversitelerinde ise hocaların hiçbir ücret almaması', 'Avrupa üniversitelerinde yalnızca tıp okutulurken medreselerde tıp ve astronominin kesinlikle yasak olması', 'Medreselerin kilise piskoposlarınca, Batı üniversitelerinin ise doğrudan şehir kadılarınca denetlenmesi'], 'İslam dünyasında icazet çoğunlukla müderrisin şahsına ve ilmi silsilesine bağlıyken, Avrupa üniversitesi lonca tüzel kişiliği adına kurumsal derece vermiştir.'),
  ('999-1003 yılları arasında Papa II. Sylvester adıyla papalık yapan ve gençliğinde Endülüs/Mağrip İslam ilim çevreleriyle temas kurarak Hint-Arap rakamlarını ve usturlabı Avrupa\'ya tanıtan bilgin kimdir?', 'Aurillaclı Gerbert', ['Cremonalı Gerard', 'Pizalı Leonardo Fibonacci', 'Bathlı Adelard'], 'Aurillaclı Gerbert (Papa II. Sylvester), İberya üzerinden İslam matematik ve astronomi birikimini Hristiyan Avrupa\'ya aktaran öncü isimlerdendir.'),
  ('Mısır\'da 1961 yılında çıkarılan bir kanunla El-Ezher\'e tıp, mühendislik, ziraat ve işletme gibi seküler fakülteler ekleyerek kurumu modern devlet üniversitesi yapısına dönüştüren lider kimdir?', 'Cemal Abdünnasır', ['Mehmed Ali Paşa', 'Enver Sedat', 'Kral I. Fuad'], 'Cemal Abdünnasır döneminde 1961\'de çıkarılan yasayla El-Ezher geleneksel dini ilimlerin yanına modern pozitif bilim fakültelerinin eklendiği bir üniversiteye dönüştürülmüştür.'),
  ('14 Mart 1827\'de Tıbhane-i Amire ile aynı dönemde cerrah yetiştirmek üzere kurulan ve 1839\'da Tıbhane ile birleştirilerek Mekteb-i Tıbbiye-i Adliye-i Şahane\'yi oluşturan kurum hangisidir?', 'Cerrahhane-i Amire', ['Darüşşifa-i Süleymaniye', 'Haseki Bimarhanesi', 'Hamidiye Etfal Hastanesi'], 'II. Mahmud döneminde Tıbhane-i Amire\'nin yanı sıra Cerrahhane-i Amire kurulmuş, 1839\'da iki okul Galatasaray\'da Mekteb-i Tıbbiye çatısı altında birleştirilmiştir.'),
  ('1898 yılında Alman Profesör Robert Rieder ve Georg Deycke yönetiminde askeri hekimlere uygulamalı klinik uzmanlık eğitimi vermek üzere İstanbul\'da açılan kurum hangisidir?', 'Gülhane Seririyat Hastanesi', ['Bezmiâlem Gureba Hastanesi', 'Şişli Etfal Hastanesi', 'Zeynep Kâmil Hastanesi'], 'II. Abdülhamid döneminde 1898\'de açılan Gülhane Seririyat Hastanesi ve Tatbikat Mektebi, modern uzmanlık ve klinik tıp eğitiminin öncüsü olmuştur.'),
  ('Mekteb-i Mülkiye\'de uzun yıllar müdürlük ve tarih hocalığı yapan, son Osmanlı vak\'anüvisi ve TBMM\'nin en yaşlı üyesi olarak ikinci dönem açılışını gerçekleştiren eğitimci kimdir?', 'Abdurrahman Şeref Bey', ['Ahmet Vefik Paşa', 'Mizancı Murad Bey', 'Süleyman Hüsnü Paşa'], 'Abdurrahman Şeref Bey, hem Galatasaray Sultanisi hem de Mekteb-i Mülkiye müdürlüğü yapmış, pek çok Osmanlı ve Cumhuriyet bürokratının yetişmesinde rol oynamıştır.'),
  ('II. Abdülhamid Dönemi\'nde Mekteb-i Mülkiye, Mekteb-i Tıbbiye ve Mekteb-i Harbiye gibi bizzat padişahın himaye edip geliştirdiği modern yüksekokulların siyasi tarih açısından beklenmedik sonucu ne olmuştur?', 'İstibdat yönetimine karşı meşrutiyeti savunan Jön Türk ve İttihat-Terakki muhalefetinin tam da bu okullardaki öğrenciler arasından doğması', ['Bu okullardan mezun olan tüm öğrencilerin modern bilimleri reddederek geleneksel medrese müderrisliğine geçmesi', 'Öğrencilerin siyasetten tamamen uzak durarak 1908 İhtilali\'ne karşı mutlak monarşiyi savunan alaylar kurması', 'Okulların yabancı dil eğitimini bırakarak yalnızca saray protokolü dersleriyle yetinmesi'], 'İmparatorluğu kurtarmak ve modern bürokrasi kurmak için büyütülen Tıbbiye, Harbiye ve Mülkiye; Batı düşüncesiyle tanışan meşrutiyetçi muhalefetin ana ocağı haline gelmiştir.'),
  ('II. Meşrutiyet döneminde Galatasaray Mekteb-i Sultanisi müdürlüğü yapan ünlü şair Tevfik Fikret\'in okulda yaptığı yenilikler nedeniyle muhafazakâr çevrelerle çatışmasına yol açan gelişmelerden biri nedir?', 'Konferans salonu, laboratuvar ve modern pedagojik disiplin kurarken geleneksel mescit/merasim uygulamalarını yeniden düzenlemesi', ['Okuldaki Türkçe derslerini tamamen kaldırarak yalnızca Rusça ve Almanca eğitim verilmesini emretmesi', 'Galatasaray\'ı ticaret lisesine dönüştürerek edebiyat ve tarih derslerini müfredattan çıkarması', 'Okulun Beyoğlu\'ndaki binasını yıktırarak öğrencileri Edirne\'deki askeri kışlalara taşıması'], 'Tevfik Fikret Galatasaray\'da çağdaş eğitim ortamı, kütüphane ve laboratuvarlar kurmuş; ancak laik-modern tutumu ve bütçe kesintilerine tepkisi nedeniyle istifa etmiştir.'),
  ('1884 yılında sivil yol, köprü ve bayındırlık mühendisi yetiştirmek üzere Mühendishane bünyesinde sivil şube olarak açılan ve İTÜ\'nün doğrudan sivil öncülü olan okul hangisidir?', 'Hendese-i Mülkiye Mektebi', ['Halkalı Ziraat Mekteb-i Âlisi', 'Orman ve Maadin Mektebi', 'Kondüktör Mekteb-i Âlisi'], 'Almanya\'daki teknik yüksekokullar örnek alınarak 1884\'te kurulan Hendese-i Mülkiye, 1909\'da Mühendis Mekteb-i Âlisi, 1944\'te ise İstanbul Teknik Üniversitesi olmuştur.'),
  ('1900 yılında açılan Darülfünun-ı Şahane\'nin başlangıçta sahip olduğu üç temel şube (fakülte) aşağıdakilerden hangisinde doğru verilmiştir?', 'Ulum-ı Âliye-i Diniye, Edebiyat ve Ulum-ı Riyaziye ve Tabiiye', ['Denizcilik, Madencilik ve Güzel Sanatlar', 'Ziraat, Veterinerlik ve Ormancılık', 'Siyasal Bilgiler, Diş Hekimliği ve Eczacılık'], '1900 nizamnamesine göre Darülfünun-ı Şahane çekirdek olarak Ulum-ı Âliye-i Diniye (İlahiyat), Ulum-ı Riyaziye ve Tabiiye (Fen) ve Edebiyat şubelerinden oluşmuş, Hukuk ve Mülki Tıbbiye de kuruma bağlanmıştır.'),
  ('II. Meşrutiyet Dönemi\'nde Darülfünun Edebiyat Fakültesi\'nde ilk kez "İçtimaiyat" (Sosyoloji) kürsüsünü kurarak sosyolojinin Türkiye\'de akademik disiplin olmasını sağlayan düşünür kimdir?', 'Ziya Gökalp', ['Prens Sabahaddin', 'Ahmet Ağaoğlu', 'Yusuf Kemal Tengirşenk'], 'Ziya Gökalp, 1914 yılında Darülfünun Edebiyat Medresesi\'nde Türkiye\'nin ve İslam dünyasının ilk bağımsız sosyoloji kürsüsünü kurmuştur.'),
  ('TBMM\'de 3 Mart 1924 tarihinde Tevhid-i Tedrisat Kanunu teklifini 50\'den fazla milletvekili arkadaşıyla birlikte Meclis Başkanlığına sunan Saruhan (Manisa) Milletvekili kimdir?', 'Hüseyin Vasıf Çınar', ['İsmet İnönü', 'Ali Fethi Okyar', 'Celal Bayar'], 'Saruhan Milletvekili Vasıf (Çınar) Bey ve arkadaşlarının verdiği kanun teklifi Meclis\'te kabul edilerek Tevhid-i Tedrisat Kanunu yasalaşmış, hemen ardından Vasıf Bey Maarif Vekili olmuştur.'),
  ('1928 yılında İstanbul\'daki Amerikan Kız Koleji\'nde (Bursa Amerikan Kız Koleji olayı) bazı Müslüman Türk öğrencilerin Hristiyanlaştırıldığının ortaya çıkması üzerine Maarif Vekaleti hangi kararı almıştır?', 'Okulu kapatarak sorumlular hakkında yasal işlem başlatılması', ['Yabancı okullara dini propaganda serbestisi tanıyan yeni bir anlaşma imzalanması', 'Kolejin yönetiminin doğrudan ABD Büyükelçiliği\'ne devredilmesi', 'Türkiye\'deki tüm özel ve resmi kız liselerinin süresiz kapatılması'], 'Ocak 1928\'deki Bursa Amerikan Kız Koleji hadisesi laiklik ve Tevhid-i Tedrisat ilkelerine aykırı bulunmuş, okul derhal kapatılmıştır.'),
  ('Şubat-Mart 1926\'da Sovyetler Birliği sınırları içindeki hangi şehirde toplanan Birinci Türkoloji Kongresi\'nde Türk halklarının Latin alfabesine geçmesi kararı alınmış ve Türkiye\'den Fuat Köprülü katılmıştır?', 'Bakü', ['Taşkent', 'Kazan', 'Semerkant'], '1926 Bakü Türkoloji Kongresi\'ne Türkiye\'den Fuat Köprülü ve Hüseyinzade Ali Turan katılmış, kongrede Latin esaslı ortak alfabe eğilimi öne çıkmıştır.'),
  ('Millet Mektepleri teşkilatında köy ve kasabalarda sabit okul bulunmayan yerlere ulaşmak amacıyla oluşturulan eğitim birimlerine ne ad verilmiştir?', 'Seyyar (Gezici) Dershaneler', ['Köy Eğitmen Kursları', 'Bölge Yatılı Okulları', 'Halk Odaları Şubeleri'], 'Sabit öğretmeni ve okulu olmayan köylerde halkı okuryazar kılmak amacıyla gezici öğretmenlerin görev yaptığı Seyyar Millet Mektebi dershaneleri kurulmuştur.'),
  ('Cumhuriyet\'in erken döneminde geliştirilen "Türk Tarih Tezi"nin uluslararası ve ulusal düzlemde karşı çıkmayı amaçladığı temel önyargı aşağıdakilerden hangisidir?', 'Türkleri yalnızca Osmanlı ve savaşçılıkla sınırlayan, Batı oryantalizminin Türkleri "uygarlık kuramayan ikinci sınıf ırk" sayan iddiaları', ['Anadolu\'da Hititler ve Sümerler öncesinde hiçbir insan yerleşiminin bulunmadığı yönündeki coğrafi teoriler', 'Avrupa devletlerinin Orta Çağ boyunca tüm bilimsel buluşları Çinlilerden doğrudan aldığını savunan görüşler', 'Osmanlı İmparatorluğu\'nun 16. yüzyılda Akdeniz ticaretinde hiçbir etkisinin olmadığını öne süren iktisat tezleri'], 'Batılı bazı ders kitaplarında Türklerin "sarı ırktan ve medeniyete katkısız" gösterilmesine tepki olarak Atatürk, Türklerin kadim uygarlıkların kurucu unsurlarından olduğunu bilimsel araştırmalarla göstermek istemiştir.'),
  ('1930\'lu yıllarda Türk Dil Kurumu çalışmalarında gündeme gelen "Güneş-Dil Teorisi"nin dil sadeleştirme sürecindeki pratik işlevi ne olmuştur?', 'Halk diline yerleşmiş bazı yabancı kökenli kelimelerin de kökte Türkçe olduğu varsayımıyla aşırı tasfiyeciliği frenlemesi', ['Türkçedeki tüm fiil çekimlerinin kaldırılarak yerine Fransızca gramer kurallarının getirilmesi', 'Anadolu ağızlarından yapılan söz derleme çalışmalarının tamamen yasaklanmasına neden olması', 'Arap alfabesine geri dönülmesi için dilbilimsel bir gerekçe oluşturması'], 'Öz Türkçecilik akımının günlük dilde iletişimi zorlaştıran aşırı tasfiyeci noktaya varması üzerine Güneş-Dil Teorisi, yerleşik kelimeleri koruyan yumuşatıcı bir geçiş sağlamıştır.'),
  ('Türk Dil Kurumu\'nda 1934\'ten itibaren başuzman olarak görev yapan, geniş dil bilgisi nedeniyle Atatürk\'ün kendisine "Dilaçar" soyadını verdiği Ermeni asıllı Türk dilbilimci kimdir?', 'Agop Martayan', ['Bedros Keresteciyan', 'Berç Keresteciyan Türker', 'Kevork Pamukciyan'], 'Birçok dili bilen Agop Martayan, Birinci Türk Dil Kurultayı\'na davet edilmiş, TDK başuzmanı olmuş ve Atatürk tarafından kendisine "Dilaçar" soyadı verilmiştir.'),
  ('1933 Üniversite Reformu öncesinde Darülfünun eminliği (rektörlüğü) yapmış olan ve "İslam ve Türk İllerinde Fütüvvet Teşkilatı" veya Türk edebiyatı tarihi çalışmalarıyla tanınıp yeni üniversitede de görev alan ünlü tarihçi kimdir?', 'Mehmed Fuat Köprülü', ['İsmail Hakkı Uzunçarşılı', 'Mükrimin Halil Yinanç', 'Zeki Velidi Togan'], 'Darülfünun Emini de olmuş olan Fuat Köprülü, uluslararası düzeydeki bilimsel yayınları sayesinde 1933 reformu sonrasında İstanbul Üniversitesi\'nde kürsüsünü koruyan seçkin isimlerdendir.'),
  ('1933 Üniversite Reformu ile Darülfünun bünyesindeki "medrese" (fakülte) adlandırması bırakılarak hangi terim resmen benimsenmiş ve İlahiyat Fakültesi neye dönüştürülmüştür?', '"Fakülte" terimi benimsenmiş, İlahiyat Fakültesi ise Edebiyat Fakültesi\'ne bağlı İslam Tetkikleri Enstitüsü\'ne dönüştürülmüştür', ['"Yüksekokul" terimi benimsenmiş, İlahiyat Fakültesi ise Ankara\'daki Diyanet İşleri Başkanlığına devredilmiştir', '"Akademi" terimi benimsenmiş, İlahiyat Fakültesi ise Şer\'iye Mahkemeleri Yüksek Mektebi yapılmıştır', '"Darülmesai" terimi benimsenmiş, İlahiyat Fakültesi ise Güzel Sanatlar Akademisi ile birleştirilmiştir'], 'Reformla üniversite, fakülte, rektör ve dekan terimleri yerleşmiş; öğrenci azlığı da gerekçe gösterilerek İlahiyat Fakültesi yerine İslam Tetkikleri Enstitüsü kurulmuştur.'),
  ('1933 yılında Nazi Almanyası\'ndan gelen bilim insanları arasında yer alıp İstanbul Üniversitesi Rasathanesi\'ni kuran astronomi profesörü kimdir?', 'Erwin Finlay-Freundlich', ['Curt Kosswig', 'Alfred Heilbronn', 'Rudolf Nissen'], 'Albert Einstein\'ın yakın çalışma arkadaşlarından astronom Erwin Finlay-Freundlich, İstanbul Üniversitesi\'nde modern Astronomi Enstitüsü ve Rasathanesi\'ni kurmuştur.'),
  ('1933 Üniversite Reformu ile İstanbul Üniversitesi Tıp Fakültesi Cerrahi Kliniği\'nin başına geçen ve modern göğüs/genel cerrahinin Türkiye\'de gelişmesini sağlayan ünlü Alman cerrah kimdir?', 'Rudolf Nissen', ['Erich Frank', 'Wilhelm Liepmann', 'Hugo Braun'], 'Dünyaca ünlü cerrah Prof. Dr. Rudolf Nissen, 1933-1939 yılları arasında İstanbul Üniversitesi 1. Cerrahi Kliniği\'ni yöneterek çok sayıda Türk cerrah yetiştirmiştir.'),
  ('1933 Üniversite Reformu ile kurulan İstanbul Üniversitesi\'nin idari yapısı 1924 Darülfünun Kanunu ile karşılaştırıldığında özerklik açısından nasıl bir değişim yaşanmıştır?', '1924\'teki idari özerklik daraltılarak üniversite Maarif Vekaleti\'nin sıkı yönlendirme ve denetimine bağlanmış, yeniden özerklik 1946 Üniversiteler Kanunu ile verilmiştir', ['Maarif Vekaleti\'nin üniversite üzerindeki tüm bütçe ve atama yetkileri kaldırılarak tam bağımsız öğrenci loncası yönetimine geçilmiştir', 'Üniversite yönetimi doğrudan Milletler Cemiyeti\'nin İsviçre\'deki eğitim komisyonuna devredilmiştir', 'Rektör ve dekanların halk oylamasıyla beş yılda bir seçilmesi uygulaması başlatılmıştır'], '1933\'teki 2252 sayılı kanun devrimci dönüşümü sağlamak için Maarif Vekili\'ne geniş müdahale yetkisi tanımış; bilimsel ve idari özerklik ise 1946\'daki 4936 sayılı Üniversiteler Kanunu ile tesis edilmiştir.'),
  ('1933 yılında Albert Einstein\'ın dönemin Türkiye Cumhuriyeti Başbakanı İsmet İnönü\'ye gönderdiği tarihi mektubun konusu aşağıdakilerden hangisidir?', 'Almanya\'da görev yapamayan kırk kadar bilim insanı ve hekimin Türkiye\'de çalışmalarını sürdürmelerine izin verilmesi ricası', ['İstanbul Üniversitesi Fizik Bölümü başkanlığına kendisinin atanması yönündeki resmi başvurusu', 'İzafiyet teorisinin Türkiye\'deki lise fizik ders kitaplarından çıkarılmasına yönelik sitemi', 'Boğaziçi\'nde uluslararası bir nükleer araştırma laboratuvarı kurulması için maddi kredi talebi'], 'Eylül 1933\'te OSE örgütü onursal başkanı sıfatıyla mektup yazan Einstein, Almanya\'dan ayrılmak zorunda kalan bilim insanlarının Türkiye\'ye kabulünü rica etmiş, bu süreç Schwartz\'ın yürüttüğü ana kanalla birleşerek yüzlerce uzmanın gelişiyle sonuçlanmıştır.'),
  ('İbn Sina\'nın "El-Kanun fi\'t-Tıb" adlı eseri 12. yüzyılda Cremonalı Gerard tarafından Latinceye çevrildikten sonra hangi Avrupa üniversitelerinin tıp fakültelerinde yüzyıllarca temel ders kitabı olarak okutulmuştur?', 'Bologna, Montpellier ve Paris üniversiteleri', ['Yalnızca Atina ve İskenderiye antik okulları', 'Sadece 19. yüzyılda kurulan Amerikan kolejleri', 'Yalnızca İskandinav denizcilik okulları'], 'İbn Sina\'nın Kanun (Canon Medicinae) adlı eseri Bologna, Montpellier, Padova ve Paris gibi Avrupa üniversitelerinde 17. yüzyıla kadar temel tıp referansı olarak okutulmuştur.'),
  ('17. ve 18. yüzyıllarda Osmanlı medreselerinde Kâtip Çelebi ve Koçi Bey risalelerinde de eleştirilen gerilemenin en temel iki nedeni aşağıdakilerden hangisinde doğru verilmiştir?', 'Akli ve riyazi ilimlerin müfredattan dışlanması ile alim çocuklarına ayrıcalıklı müderrislik veren "beşik ulemalığı" usulünün yaygınlaşması', ['Medreselerde laboratuvar deneylerine aşırı bütçe ayrılması nedeniyle hazinenin iflas etmesi', 'Avrupa\'dan gelen binlerce yabancı öğrencinin medrese kontenjanlarını doldurması', 'Müderrislerin tamamının deniz aşırı coğrafi keşif seferlerine katılarak İstanbul\'u terk etmesi'], 'Felsefe, matematik ve astronomi gibi akli ilimlerin zayıflaması ve liyakat yerine soy ayrıcalığına dayanan beşik ulemalığı medrese sistemini yozlaştırmış, Osmanlı\'yı Hendesehane gibi yeni okullar açmaya yöneltmiştir.'),
];
